// ==================== 生成智能出行标签 ====================
function generateSmartTags(destination, options) {
    const container = document.getElementById('smartTagsContainer');
    container.innerHTML = '';

    const tags = [];
    const days = parseInt(options.days);
    const avoid = options.avoid;
    const hotelPref = options.hotelPref;
    const foodPref = options.foodPref;
    const preference = options.preference;

    // 基于天数的标签
    if (days === 2) {
        tags.push({ name: '短途周末', emoji: '🌤️' });
    } else if (days === 3) {
        tags.push({ name: '休闲放松', emoji: '😌' });
    } else if (days >= 5) {
        tags.push({ name: '深度游', emoji: '🧳' });
    }

    // 基于体力强度的标签
    if (avoid === 'lazy') {
        tags.push({ name: '佛系懒人', emoji: '😴' });
    } else if (avoid === 'mountain') {
        tags.push({ name: '轻松游玩', emoji: '🚶' });
    }

    // 基于饮食偏好的标签
    if (foodPref === 'local') {
        tags.push({ name: '美食之旅', emoji: '🍜' });
    } else if (foodPref === 'trendy') {
        tags.push({ name: '网红打卡', emoji: '📸' });
    } else if (foodPref === 'spicy') {
        tags.push({ name: '重口味', emoji: '🌶️' });
    } else if (foodPref === 'light') {
        tags.push({ name: '清淡饮食', emoji: '🥬' });
    }

    // 基于住宿偏好的标签
    if (hotelPref === 'budget') {
        tags.push({ name: '经济实惠', emoji: '💰' });
    } else if (hotelPref === 'unique') {
        tags.push({ name: '特色住宿', emoji: '🏯' });
    } else if (hotelPref === 'trendy') {
        tags.push({ name: '网红酒店', emoji: '✨' });
    }

    // 基于游玩偏好的标签
    if (preference === 'nature') {
        tags.push({ name: '自然风光', emoji: '🏞️' });
    } else if (preference === 'city') {
        tags.push({ name: '城市逛吃', emoji: '🏙️' });
    } else if (preference === 'niche') {
        tags.push({ name: '小众秘境', emoji: '🌲' });
    } else if (preference === 'trendy') {
        tags.push({ name: '网红打卡', emoji: '📸' });
    } else if (preference === 'history') {
        tags.push({ name: '人文慢游', emoji: '🏛️' });
    }

    // 基于目的地特点的标签
    if (destination.name === '三亚' || destination.name === '厦门' || destination.name === '威海' || destination.name === '青岛' || destination.name === '日照') {
        tags.push({ name: '海滨度假', emoji: '🏖️' });
    } else if (destination.name === '张家界' || destination.name === '丽江' || destination.name === '恩施' || destination.name === '赛里木湖' || destination.name === '新疆伊犁') {
        tags.push({ name: '轻徒步', emoji: '🥾' });
    } else if (destination.name === '北京' || destination.name === '西安' || destination.name === '南京' || destination.name === '洛阳' || destination.name === '敦煌') {
        tags.push({ name: '历史文化', emoji: '📜' });
    }

    // 去重
    const uniqueTags = [];
    const seen = new Set();
    tags.forEach(tag => {
        if (!seen.has(tag.name)) {
            seen.add(tag.name);
            uniqueTags.push(tag);
        }
    });

    // 最多显示5个标签
    const finalTags = uniqueTags.slice(0, 5);

    // 创建标签元素
    finalTags.forEach(tag => {
        const tagElement = document.createElement('span');
        tagElement.className = 'smart-tag';
        tagElement.innerHTML = `${tag.emoji} ${tag.name}`;
        container.appendChild(tagElement);
    });
}

