// 预算反向定制弹窗控制
function openBudgetReverseModal() {
    const modal = document.getElementById('budgetReverseModal');
    modal.classList.remove('hidden');
    modal.classList.add('flex');
    setTimeout(() => {
        modal.style.opacity = '1';
        modal.querySelector('div').style.transform = 'scale(1)';
    }, 10);
}

function closeBudgetReverseModal() {
    const modal = document.getElementById('budgetReverseModal');
    modal.style.opacity = '0';
    modal.querySelector('div').style.transform = 'scale(0.95)';
    setTimeout(() => {
        modal.classList.remove('flex');
        modal.classList.add('hidden');
        document.getElementById('budgetMatchResults').classList.add('hidden');
    }, 300);
}

// 预算天数选择
function setupBudgetDaysButtons() {
    const buttons = document.querySelectorAll('[data-type="budgetDays"]');
    buttons.forEach(btn => {
        btn.addEventListener('click', function() {
            buttons.forEach(b => b.classList.remove('selected', 'border-green-400', 'bg-green-50'));
            this.classList.add('selected', 'border-green-400', 'bg-green-50');
            budgetReverseOptions.days = parseInt(this.dataset.value);
        });
    });
}

// 匹配目的地
// ==================== 预算反向定制匹配 ====================
function matchDestinationsByBudget() {
    try {
        // 读取用户输入
        const budgetInput = document.getElementById('budgetAmount').value;
        const days = budgetReverseOptions.days;
        const departureCity = document.getElementById('departureCity').value.trim();

        // 验证输入
        if (!budgetInput || budgetInput.trim() === '') {
            showToast('请输入预算金额', 'warning');
            return;
        }

        const budget = parseInt(budgetInput);

        if (isNaN(budget) || budget < 100) {
            showToast('请输入有效的预算金额（最低100元）', 'warning');
            return;
        }

        if (!days) {
            showToast('请选择出行天数', 'warning');
            return;
        }

        if (!departureCity) {
            showToast('请输入出发城市', 'warning');
            return;
        }

        // 保存用户选择
        budgetReverseOptions.budget = budget;
        budgetReverseOptions.departureCity = departureCity;

        // 匹配符合预算的目的地
        const matchedCities = [];

        destinations.forEach(city => {
            if (cityBudgetData[city.id] && cityBudgetData[city.id][days]) {
                const cityBudget = cityBudgetData[city.id][days];
                if (cityBudget <= budget) {
                    matchedCities.push({
                        ...city,
                        estimatedBudget: cityBudget,
                        budgetPercentage: Math.round((cityBudget / budget) * 100)
                    });
                }
            }
        });

        // 按预算占比排序
        matchedCities.sort((a, b) => a.budgetPercentage - b.budgetPercentage);

        // 渲染匹配结果
        renderBudgetMatchResults(matchedCities);
    } catch (err) {
        console.error('匹配目的地时出错:', err);
        showToast('匹配失败，请重试', 'error');
    }
}

// 渲染预算匹配结果
function renderBudgetMatchResults(cities) {
    const resultsList = document.getElementById('matchResultsList');
    resultsList.innerHTML = '';

    if (cities.length === 0) {
        resultsList.innerHTML = `
            <div class="text-center py-8">
                <p class="text-4xl mb-4">💰</p>
                <p class="text-lg text-gray-600">暂无符合预算的目的地</p>
                <p class="text-gray-400 mt-2">建议增加预算或减少出行天数</p>
            </div>
        `;
    } else {
        cities.forEach(city => {
            const cityCard = document.createElement('div');
            cityCard.className = 'bg-white rounded-xl shadow-md p-4 border border-gray-100 hover:shadow-lg transition-shadow duration-300';
            cityCard.innerHTML = `
                <div class="flex items-center justify-between">
                    <div class="flex items-center gap-3">
                        <div class="text-4xl">${city.emoji}</div>
                        <div>
                            <h5 class="font-bold text-gray-700">${city.name}</h5>
                            <p class="text-sm text-gray-500">${city.description}</p>
                        </div>
                    </div>
                    <div class="text-right">
                        <div class="font-semibold text-green-600">¥${city.estimatedBudget}</div>
                        <div class="text-xs text-gray-500">预算占比 ${city.budgetPercentage}%</div>
                    </div>
                </div>
                <div class="mt-4">
                    <div class="w-full bg-gray-200 rounded-full h-2 mb-2">
                        <div class="bg-gradient-to-r from-green-400 to-teal-400 h-2 rounded-full" style="width: ${city.budgetPercentage}%"></div>
                    </div>
                    <button class="selectBudgetDestinationBtn w-full py-2 bg-gradient-to-r from-green-400 to-teal-400 text-white font-bold rounded-full shadow-md hover:shadow-lg transition-all duration-300" data-city="${city.id}">
                        选择此目的地
                    </button>
                </div>
            `;
            resultsList.appendChild(cityCard);
        });

        // 绑定选择按钮事件
        document.querySelectorAll('.selectBudgetDestinationBtn').forEach(btn => {
            btn.addEventListener('click', function() {
                const cityId = this.dataset.city;
                const selectedCity = destinations.find(city => city.id === cityId);
                if (selectedCity) {
                    // 选择城市并关闭弹窗
                    selectDestination(selectedCity);
                    closeBudgetReverseModal();
                    // 滚动到生成按钮位置
                    window.scrollTo({ top: 600, behavior: 'smooth' });
                }
            });
        });
    }

    document.getElementById('budgetMatchResults').classList.remove('hidden');
}

// 绑定预算反向定制相关事件
function setupBudgetReverseEvents() {
    console.log('setupBudgetReverseEvents 被调用');

    const budgetReverseBtn = document.getElementById('budgetReverseBtn');
    const closeBtn = document.getElementById('closeBudgetReverseModal');
    const matchBtn = document.getElementById('matchDestinationsBtn');

    if (budgetReverseBtn) {
        console.log('绑定预算反向定制按钮');
        budgetReverseBtn.addEventListener('click', openBudgetReverseModal);
    }

    if (closeBtn) {
        closeBtn.addEventListener('click', closeBudgetReverseModal);
    }

    if (matchBtn) {
        console.log('绑定开始匹配按钮');
        matchBtn.addEventListener('click', function() {
            console.log('开始匹配按钮被点击');
            matchDestinationsByBudget();
        });
    } else {
        console.log('未找到开始匹配按钮!');
    }

    setupBudgetDaysButtons();
}

// ==================== 长辈模式功能 ====================
let isSeniorMode = false;

// 切换长辈模式
function toggleSeniorMode() {
    isSeniorMode = !isSeniorMode;
    const body = document.body;
    const seniorModeBtn = document.getElementById('seniorModeBtn');
    
    if (isSeniorMode) {
        body.classList.add('senior-mode');
        seniorModeBtn.textContent = '👴 退出长辈模式';
        seniorModeBtn.classList.remove('bg-gradient-to-r', 'from-orange-400', 'to-red-400');
        seniorModeBtn.classList.add('bg-gradient-to-r', 'from-blue-400', 'to-green-400');
        addSpeechButton();
        setupSeniorModeSpeech();
        autoSpeakFullGuide();
        showToast('已开启长辈模式');
    } else {
        body.classList.remove('senior-mode');
        seniorModeBtn.textContent = '👴 长辈模式';
        seniorModeBtn.classList.remove('bg-gradient-to-r', 'from-blue-400', 'to-green-400');
        seniorModeBtn.classList.add('bg-gradient-to-r', 'from-orange-400', 'to-red-400');
        removeSpeechButton();
        setupSeniorModeSpeech();
        stopSpeech();
        showToast('已退出长辈模式');
    }
}

// 添加语音播报按钮
function addSpeechButton() {
    // 检查是否已存在语音播报按钮
    if (document.querySelector('.speech-btn')) return;
    
    const speechBtn = document.createElement('button');
    speechBtn.className = 'speech-btn';
    speechBtn.innerHTML = '🔊';
    speechBtn.title = '语音播报攻略';
    speechBtn.addEventListener('click', toggleSpeech);
    document.body.appendChild(speechBtn);
}

// 移除语音播报按钮
function removeSpeechButton() {
    const speechBtn = document.querySelector('.speech-btn');
    if (speechBtn) {
        speechBtn.remove();
    }
}

// 语音播报功能
function toggleSpeech() {
    if ('speechSynthesis' in window) {
        const guideContent = document.getElementById('guideSection');
        if (guideContent) {
            const text = guideContent.textContent;
            const speech = new SpeechSynthesisUtterance(text);
            speech.lang = 'zh-CN';
            speech.rate = 0.9;
            speech.pitch = 1;
            speech.volume = 1;
            
            // 停止之前的语音
            window.speechSynthesis.cancel();
            // 开始新的语音
            window.speechSynthesis.speak(speech);
            
            showToast('开始语音播报');
        }
    } else {
        showToast('您的浏览器不支持语音播报功能');
    }
}

// 绑定长辈模式相关事件
function setupSeniorModeEvents() {
    document.getElementById('seniorModeBtn').addEventListener('click', toggleSeniorMode);
}

// ==================== 全页面语音播报系统 ====================
let currentSpeech = null;
let isSpeaking = false;
let isPaused = false;
let currentSection = null;

const sectionNames = {
    'plans': '旅行方案',
    'transport': '交通建议',
    'food': '必吃美食',
    'hotel': '住宿推荐',
    'avoid': '避坑提醒',
    'tips': '出行小贴士',
    'budget': '预算估算',
    'localTips': '本地人私藏避坑指南'
};

// 获取板块文本内容
function getSectionText(sectionId) {
    const section = document.getElementById(sectionId + 'Section');
    if (!section) return '';
    
    let text = sectionNames[sectionId] || sectionId;
    const heading = section.querySelector('h3');
    if (heading) text += '，' + heading.textContent;
    
    // 获取所有文本内容
    const content = section.querySelector('.space-y-4, .space-y-6, .grid, #planAContent, #planBContent');
    if (content) {
        text += '，' + content.textContent.replace(/\s+/g, ' ').trim();
    }
    
    return text;
}

// 播放指定板块的语音
function speakSection(sectionId) {
    if (!('speechSynthesis' in window)) {
        showToast('您的浏览器不支持语音播报功能');
        return;
    }
    
    // 如果正在播放其他板块，先停止
    if (isSpeaking && currentSection !== sectionId) {
        stopSpeech();
    }
    
    const text = getSectionText(sectionId);
    if (!text) {
        showToast('该板块暂无内容可朗读');
        return;
    }
    
    // 如果点击的是当前播放的板块，切换暂停/继续
    if (currentSection === sectionId && isSpeaking) {
        if (isPaused) {
            window.speechSynthesis.resume();
            isPaused = false;
            updateSpeechButton(sectionId, true);
            showToast('继续朗读');
        } else {
            window.speechSynthesis.pause();
            isPaused = true;
            updateSpeechButton(sectionId, false);
            showToast('暂停朗读');
        }
        return;
    }
    
    // 开始新的语音播放
    stopSpeech();
    currentSection = sectionId;
    currentSpeech = new SpeechSynthesisUtterance(text);
    currentSpeech.lang = 'zh-CN';
    currentSpeech.rate = isSeniorMode ? 0.8 : 0.9;
    currentSpeech.pitch = 1;
    currentSpeech.volume = 1;
    
    currentSpeech.onstart = () => {
        isSpeaking = true;
        isPaused = false;
        updateSpeechButton(sectionId, true);
    };
    
    currentSpeech.onend = () => {
        isSpeaking = false;
        isPaused = false;
        currentSection = null;
        updateSpeechButton(sectionId, false);
    };
    
    currentSpeech.onerror = () => {
        isSpeaking = false;
        isPaused = false;
        currentSection = null;
        updateSpeechButton(sectionId, false);
    };
    
    window.speechSynthesis.speak(currentSpeech);
    showToast('正在朗读：' + (sectionNames[sectionId] || sectionId));
}

// 停止语音播放
function stopSpeech() {
    if ('speechSynthesis' in window) {
        window.speechSynthesis.cancel();
    }
    if (currentSection) {
        updateSpeechButton(currentSection, false);
    }
    isSpeaking = false;
    isPaused = false;
    currentSection = null;
}

// 更新语音按钮状态
function updateSpeechButton(sectionId, playing) {
    const btn = document.querySelector(`.section-speech-btn[data-section="${sectionId}"]`);
    if (btn) {
        if (playing) {
            btn.classList.add('playing');
            btn.querySelector('span').textContent = isPaused ? '▶️' : '⏸️';
        } else {
            btn.classList.remove('playing');
            btn.querySelector('span').textContent = '🔊';
        }
    }
}

// 绑定各板块语音按钮事件
function setupSectionSpeechButtons() {
    document.querySelectorAll('.section-speech-btn').forEach(btn => {
        btn.addEventListener('click', () => {
            const section = btn.dataset.section;
            speakSection(section);
        });
    });
}

// 长辈模式下的标题点击朗读功能
function setupSeniorModeSpeech() {
    if (isSeniorMode) {
        // 为所有标题添加点击朗读功能
        document.querySelectorAll('h1, h2, h3, h4').forEach(title => {
            if (!title.classList.contains('speech-enabled')) {
                title.classList.add('speech-enabled');
                title.style.cursor = 'pointer';
                title.style.textDecoration = 'underline';
                title.style.textDecorationStyle = 'dotted';
                title.addEventListener('click', function() {
                    if ('speechSynthesis' in window) {
                        const speech = new SpeechSynthesisUtterance(this.textContent);
                        speech.lang = 'zh-CN';
                        speech.rate = 0.8;
                        window.speechSynthesis.speak(speech);
                    }
                });
            }
        });
    } else {
        // 移除长辈模式下的点击朗读功能
        document.querySelectorAll('.speech-enabled').forEach(title => {
            title.classList.remove('speech-enabled');
            title.style.cursor = 'default';
            title.style.textDecoration = 'none';
        });
    }
}

// 长辈模式下自动播报攻略全文
function autoSpeakFullGuide() {
    if (isSeniorMode && document.getElementById('guideSection') && !isSpeaking) {
        const guideContent = document.getElementById('guideSection');
        if (guideContent) {
            const text = guideContent.textContent;
            if ('speechSynthesis' in window) {
                const speech = new SpeechSynthesisUtterance(text);
                speech.lang = 'zh-CN';
                speech.rate = 0.8;
                speech.onend = () => {
                    isSpeaking = false;
                };
                window.speechSynthesis.speak(speech);
                isSpeaking = true;
                showToast('长辈模式：开始自动播报攻略全文');
            }
        }
    }
}

// ==================== 首次进入欢迎弹窗系统 ====================
let userProfile = {
    avatar: '🧳',
    nickname: '旅行旅人',
    gender: null,
    created: false
};

function checkFirstTimeUser() {
    const saved = localStorage.getItem('userProfile');
    if (saved) {
        userProfile = JSON.parse(saved);
        return false;
    }
    return true;
}

function showWelcomeModal() {
    const modal = document.getElementById('welcomeModal');
    modal.classList.remove('hidden');
    modal.classList.add('flex', 'show');
    modal.style.opacity = '1';
}

function hideWelcomeModal() {
    const modal = document.getElementById('welcomeModal');
    modal.classList.add('hidden');
    modal.classList.remove('flex', 'show');
    modal.style.opacity = '0';
}

function selectAvatar(avatar, gender) {
    userProfile.gender = gender;
    userProfile.avatar = avatar;
    
    document.querySelectorAll('.avatar-option').forEach(btn => {
        btn.classList.remove('selected');
    });
    document.querySelector(`.avatar-option[data-avatar="${avatar}"]`).classList.add('selected');
}

function confirmWelcome() {
    if (!userProfile.avatar) {
        showToast('请先选择一个旅行形象～', 'warning');
        return;
    }
    
    const nickname = document.getElementById('nicknameInput').value.trim();
    if (nickname) {
        userProfile.nickname = nickname;
    }
    userProfile.created = true;
    
    localStorage.setItem('userProfile', JSON.stringify(userProfile));
    hideWelcomeModal();
    
    // 更新小人形象
    updateCharacterAppearance();
    showToast('欢迎 ' + userProfile.nickname + ' 开始你的治愈之旅！🌟');
}

function setupWelcomeEvents() {
    // 性别切换事件
    document.querySelectorAll('.gender-btn').forEach(btn => {
        btn.addEventListener('click', () => {
            const gender = btn.dataset.gender;
            
            // 更新性别按钮样式
            document.querySelectorAll('.gender-btn').forEach(b => {
                b.classList.remove('selected');
                if (b.dataset.gender === 'male') {
                    b.classList.remove('bg-blue-100', 'text-blue-600');
                    b.classList.add('bg-gray-100', 'text-gray-600');
                } else {
                    b.classList.remove('bg-pink-100', 'text-pink-600');
                    b.classList.add('bg-gray-100', 'text-gray-600');
                }
            });
            btn.classList.add('selected');
            if (gender === 'male') {
                btn.classList.remove('bg-gray-100', 'text-gray-600');
                btn.classList.add('bg-blue-100', 'text-blue-600');
            } else {
                btn.classList.remove('bg-gray-100', 'text-gray-600');
                btn.classList.add('bg-pink-100', 'text-pink-600');
            }
            
            // 显示/隐藏对应性别的形象
            document.querySelectorAll('.avatar-option').forEach(opt => {
                if (opt.dataset.gender === gender) {
                    opt.classList.remove('hidden');
                } else {
                    opt.classList.add('hidden');
                }
            });
            
            // 选中新性别的第一个形象
            const firstAvatar = document.querySelector(`.avatar-option[data-gender="${gender}"]`);
            if (firstAvatar) {
                selectAvatar(firstAvatar.dataset.avatar, gender);
            }
        });
    });
    
    // 形象选择事件
    document.querySelectorAll('.avatar-option').forEach(btn => {
        btn.addEventListener('click', () => {
            selectAvatar(btn.dataset.avatar, btn.dataset.gender);
        });
    });
    
    document.getElementById('confirmWelcomeBtn').addEventListener('click', confirmWelcome);
    
    // 初始化选中第一个男款形象
    const firstMaleAvatar = document.querySelector('.avatar-option[data-gender="male"]');
    if (firstMaleAvatar) {
        selectAvatar(firstMaleAvatar.dataset.avatar, 'male');
    }
}

// ==================== 每日签到系统 ====================
let checkinData = {
    shells: 0,
    records: [],
    checkinDays: [],
    streak: 0,
    lastCheckin: null
};

function loadCheckinData() {
    const saved = localStorage.getItem('checkinData');
    if (saved) {
        checkinData = JSON.parse(saved);
    }
}

function saveCheckinData() {
    localStorage.setItem('checkinData', JSON.stringify(checkinData));
}

function getTodayString() {
    const today = new Date();
    return `${today.getFullYear()}-${today.getMonth() + 1}-${today.getDate()}`;
}

function isCheckedInToday() {
    return checkinData.checkinDays.includes(getTodayString());
}

function doCheckin() {
    if (isCheckedInToday()) {
        showToast('今日已签到过啦～明天再来吧！🌙');
        return;
    }
    
    const today = getTodayString();
    let reward = 10;
    
    // 计算连续签到
    const yesterday = new Date();
    yesterday.setDate(yesterday.getDate() - 1);
    const yesterdayStr = `${yesterday.getFullYear()}-${yesterday.getMonth() + 1}-${yesterday.getDate()}`;
    
    if (checkinData.lastCheckin === yesterdayStr) {
        checkinData.streak++;
    } else {
        checkinData.streak = 1;
    }
    
    // 7天连续签到额外奖励
    if (checkinData.streak === 7) {
        reward += 50;
        addCostumeFragment();
        showToast('🎉 连续签到7天！额外获得50贝壳+限定装扮碎片！');
    }
    
    checkinData.shells += reward;
    checkinData.checkinDays.push(today);
    checkinData.lastCheckin = today;
    checkinData.records.unshift({
        date: today,
        reward: reward,
        type: '签到'
    });
    
    saveCheckinData();
    updateCheckinUI();
    showToast('🎁 签到成功！获得' + reward + '个旅行贝壳！');
    
    // 显示贝壳飞入动画
    showShellRewardAnimation(reward);
}

function showShellRewardAnimation(amount) {
    const badge = document.getElementById('checkinBadge');
    if (badge) {
        badge.classList.add('shell-reward-animation');
        setTimeout(() => {
            badge.classList.remove('shell-reward-animation');
        }, 1000);
    }
}

function addCostumeFragment() {
    let fragments = JSON.parse(localStorage.getItem('costumeFragments') || '[]');
    fragments.push({ type: 'random', date: getTodayString() });
    localStorage.setItem('costumeFragments', JSON.stringify(fragments));
}

function updateCheckinUI() {
    document.getElementById('shellBalance').textContent = checkinData.shells;
    
    const statusEl = document.getElementById('checkinStatus');
    const btnEl = document.getElementById('doCheckinBtn');
    
    if (isCheckedInToday()) {
        statusEl.classList.remove('hidden');
        btnEl.classList.add('opacity-50');
        btnEl.disabled = true;
    } else {
        statusEl.classList.add('hidden');
        btnEl.classList.remove('opacity-50');
        btnEl.disabled = false;
    }
    
    renderCheckinCalendar();
    renderCheckinRecords();
}

function renderCheckinCalendar() {
    const container = document.getElementById('checkinCalendar');
    if (!container) return;
    
    const now = new Date();
    const year = now.getFullYear();
    const month = now.getMonth();
    
    document.getElementById('checkinMonth').textContent = `${year}年${month + 1}月`;
    
    const firstDay = new Date(year, month, 1).getDay();
    const daysInMonth = new Date(year, month + 1, 0).getDate();
    const today = now.getDate();
    
    let html = '';
    
    // 填充空白
    for (let i = 0; i < firstDay; i++) {
        html += '<div></div>';
    }
    
    // 填充日期
    for (let d = 1; d <= daysInMonth; d++) {
        const dateStr = `${year}-${month + 1}-${d}`;
        const isChecked = checkinData.checkinDays.includes(dateStr);
        const isToday = d === today;
        
        let classes = 'checkin-day';
        if (isChecked) classes += ' checked';
        if (isToday) classes += ' today';
        if (d > today) classes += ' future';
        
        html += `<div class="${classes}">${d}</div>`;
    }
    
    container.innerHTML = html;
}

function renderCheckinRecords() {
    const container = document.getElementById('checkinRecords');
    if (!container) return;
    
    if (checkinData.records.length === 0) {
        container.innerHTML = '<p class="text-gray-400 text-sm text-center py-2">暂无记录</p>';
        return;
    }
    
    container.innerHTML = checkinData.records.slice(0, 10).map(r => `
        <div class="flex justify-between text-sm">
            <span class="text-gray-600">${r.date}</span>
            <span class="text-yellow-500">+${r.reward}贝壳</span>
        </div>
    `).join('');
}

function showCheckinModal() {
    const modal = document.getElementById('checkinModal');
    modal.classList.remove('hidden');
    modal.classList.add('flex', 'show');
    modal.style.opacity = '1';
    updateCheckinUI();
}

function hideCheckinModal() {
    const modal = document.getElementById('checkinModal');
    modal.classList.add('hidden');
    modal.classList.remove('flex', 'show');
    modal.style.opacity = '0';
}

function setupCheckinEvents() {
    document.getElementById('dailyCheckinBtn').addEventListener('click', showCheckinModal);
    document.getElementById('closeCheckinModal').addEventListener('click', hideCheckinModal);
    document.getElementById('doCheckinBtn').addEventListener('click', doCheckin);
    
    document.getElementById('checkinTab').addEventListener('click', () => {
        document.getElementById('checkinTab').classList.add('text-pink-500', 'border-b-2', 'border-pink-500');
        document.getElementById('checkinTab').classList.remove('text-gray-500');
        document.getElementById('mallTab').classList.remove('text-pink-500', 'border-b-2', 'border-pink-500');
        document.getElementById('mallTab').classList.add('text-gray-500');
        document.getElementById('checkinPanel').classList.remove('hidden');
        document.getElementById('mallPanel').classList.add('hidden');
    });
    
    document.getElementById('mallTab').addEventListener('click', () => {
        document.getElementById('mallTab').classList.add('text-pink-500', 'border-b-2', 'border-pink-500');
        document.getElementById('mallTab').classList.remove('text-gray-500');
        document.getElementById('checkinTab').classList.remove('text-pink-500', 'border-b-2', 'border-pink-500');
        document.getElementById('checkinTab').classList.add('text-gray-500');
        document.getElementById('checkinPanel').classList.add('hidden');
        document.getElementById('mallPanel').classList.remove('hidden');
        renderMallItems('clothing');
    });
}

