let ownedItems = JSON.parse(localStorage.getItem('ownedItems') || '[]');
let currentCostume = null;
let currentAction = null;
let currentAccessory = null;
let currentCityBadge = null;

function renderMallItems(category) {
    const container = document.getElementById('mallItems');
    if (!container) return;
    
    const items = mallItems[category] || [];
    const generatedCities = JSON.parse(localStorage.getItem('generatedCities') || '[]');
    
    if (category === 'city') {
        container.innerHTML = items.map(item => {
            const isOwned = ownedItems.includes(item.id);
            const isLocked = item.cityRequired && !generatedCities.includes(item.cityRequired);
            const canBuy = !isOwned && !isLocked && checkinData.shells >= item.price;
            
            let classes = 'mall-item relative';
            if (isOwned) classes += ' owned';
            if (isLocked) classes += ' locked';
            
            return `
                <div class="${classes}" data-id="${item.id}" data-price="${item.price}">
                    <div class="emoji">${item.emoji}</div>
                    <div class="name">${item.name}</div>
                    <div class="price text-xs">${isOwned ? '已拥有' : isLocked ? item.desc : item.price + '贝壳'}</div>
                    ${!isOwned && !isLocked ? `<button class="mt-2 px-3 py-1 text-xs bg-pink-400 text-white rounded-full ${canBuy ? 'hover:bg-pink-500' : 'opacity-50'}" ${!canBuy ? 'disabled' : ''}>${checkinData.shells >= item.price ? '兑换' : '贝壳不足'}</button>` : ''}
                    ${isOwned ? '<div class="absolute top-1 right-1 text-green-500">✓</div>' : ''}
                </div>
            `;
        }).join('');
    } else {
        container.innerHTML = items.map(item => {
            const isOwned = ownedItems.includes(item.id);
            const isLocked = item.cityRequired && !generatedCities.includes(item.cityRequired);
            const canBuy = !isOwned && !isLocked && checkinData.shells >= item.price;
            
            let classes = 'mall-item relative';
            if (isOwned) classes += ' owned';
            if (isLocked) classes += ' locked';
            
            return `
                <div class="${classes}" data-id="${item.id}" data-price="${item.price}">
                    <div class="emoji">${item.emoji}</div>
                    <div class="name">${item.name}</div>
                    <div class="price">${isOwned ? '已拥有' : isLocked ? '需先解锁城市' : item.price + '贝壳'}</div>
                    ${!isOwned && !isLocked ? `<button class="mt-2 px-3 py-1 text-xs bg-pink-400 text-white rounded-full ${canBuy ? 'hover:bg-pink-500' : 'opacity-50'}" ${!canBuy ? 'disabled' : ''}>${checkinData.shells >= item.price ? '兑换' : '贝壳不足'}</button>` : ''}
                </div>
            `;
        }).join('');
    }
    
    container.querySelectorAll('.mall-item button').forEach(btn => {
        btn.addEventListener('click', (e) => {
            const itemEl = e.currentTarget.closest('.mall-item');
            const itemId = itemEl.dataset.id;
            const price = parseInt(itemEl.dataset.price);
            buyMallItem(itemId, price);
        });
    });
    
    renderOwnedItems();
}

function buyMallItem(itemId, price) {
    if (checkinData.shells < price) {
        showToast('贝壳不足，无法兑换');
        return;
    }
    
    checkinData.shells -= price;
    ownedItems.push(itemId);
    localStorage.setItem('ownedItems', JSON.stringify(ownedItems));
    saveCheckinData();
    
    let purchasedItem = null;
    ['clothing', 'action', 'accessory', 'city'].forEach(cat => {
        const item = mallItems[cat]?.find(i => i.id === itemId);
        if (item) {
            purchasedItem = item;
            if (cat === 'clothing') {
                currentCostume = item;
            } else if (cat === 'action') {
                currentAction = item;
            } else if (cat === 'accessory') {
                currentAccessory = item;
            } else if (cat === 'city') {
                currentCityBadge = item;
            }
        }
    });
    
    localStorage.setItem('currentCostume', JSON.stringify(currentCostume));
    localStorage.setItem('currentAction', JSON.stringify(currentAction));
    localStorage.setItem('currentAccessory', JSON.stringify(currentAccessory));
    localStorage.setItem('currentCityBadge', JSON.stringify(currentCityBadge));
    
    updateCheckinUI();
    renderOwnedItems();
    updateCharacterAppearance();
    showToast(`兑换成功！${purchasedItem?.emoji || ''}已装备到小人身上～✨`);
}

function renderOwnedItems() {
    const container = document.getElementById('ownedItems');
    if (!container) return;
    
    if (ownedItems.length === 0) {
        container.innerHTML = '<p class="text-gray-400 text-sm">暂无装扮</p>';
        return;
    }
    
    container.innerHTML = ownedItems.map(id => {
        let item = null;
        ['clothing', 'action', 'accessory', 'city'].forEach(cat => {
            if (mallItems[cat]) {
                const found = mallItems[cat].find(i => i.id === id);
                if (found) item = found;
            }
        });
        if (!item) return '';
        return `<span class="px-2 py-1 bg-gray-100 rounded-full text-lg cursor-pointer hover:bg-gray-200" title="${item.name}">${item.emoji}</span>`;
    }).join('');
}

function setupMallEvents() {
    document.querySelectorAll('.mall-category-btn').forEach(btn => {
        btn.addEventListener('click', () => {
            document.querySelectorAll('.mall-category-btn').forEach(b => {
                b.classList.remove('selected', 'bg-pink-100', 'text-pink-600');
                b.classList.add('bg-gray-100', 'text-gray-600');
            });
            btn.classList.add('selected', 'bg-pink-100', 'text-pink-600');
            btn.classList.remove('bg-gray-100', 'text-gray-600');
            renderMallItems(btn.dataset.category);
        });
    });
}

// ==================== 增强小人悬浮栏系统 ====================
let isCharacterMinimized = false;
let isDragging = false;
let dragOffsetX = 0;
let dragOffsetY = 0;

function updateCharacterAppearance() {
    const body = document.getElementById('characterBody');
    const level = document.getElementById('characterLevel');
    const expandBody = document.getElementById('expandCharacterBody');
    const badgesContainer = document.getElementById('characterBadges');
    const floatingCharacterImage = document.getElementById('characterImage');
    
    if (body) {
        let emoji = userProfile.avatar;
        if (currentAccessory) emoji = currentAccessory.emoji + ' ' + emoji;
        if (currentCostume) emoji += ' ' + currentCostume.emoji;
        if (currentCityBadge) emoji += ' ' + currentCityBadge.emoji;
        body.textContent = emoji;
    }
    
    if (expandBody) {
        let emoji = userProfile.avatar;
        if (currentAccessory) emoji = currentAccessory.emoji + ' ' + emoji;
        if (currentCostume) emoji += ' ' + currentCostume.emoji;
        if (currentCityBadge) emoji += ' ' + currentCityBadge.emoji;
        expandBody.textContent = emoji;
    }
    
    // 更新悬浮小人形象
    if (floatingCharacterImage) {
        let emoji = userProfile.avatar;
        if (currentAccessory) emoji = currentAccessory.emoji + ' ' + emoji;
        if (currentCostume) emoji += ' ' + currentCostume.emoji;
        if (currentCityBadge) emoji += ' ' + currentCityBadge.emoji;
        floatingCharacterImage.textContent = emoji;
    }
    
    // 更新等级
    const generatedCount = JSON.parse(localStorage.getItem('generatedCities') || '[]').length;
    const userLevel = Math.min(Math.floor(generatedCount / 2) + 1, 10);
    if (level) level.textContent = userLevel;
}

function showCharacterSpeech(text, duration = 3000) {
    const speechEl = document.getElementById('characterSpeech');
    const speechText = document.getElementById('speechText');
    if (speechEl && speechText) {
        speechText.textContent = text;
        speechEl.classList.remove('hidden');
        setTimeout(() => {
            speechEl.classList.add('hidden');
        }, duration);
    }
}

function minimizeCharacter() {
    const char = document.getElementById('travelCharacter');
    const panel = document.getElementById('characterExpandPanel');
    char.classList.add('minimized');
    if (panel) panel.classList.add('show');
    isCharacterMinimized = true;
}

function expandCharacter() {
    const char = document.getElementById('travelCharacter');
    const panel = document.getElementById('characterExpandPanel');
    char.classList.remove('minimized');
    if (panel) panel.classList.remove('show');
    isCharacterMinimized = false;
}

function setupCharacterDrag() {
    const char = document.getElementById('travelCharacter');
    
    char.addEventListener('mousedown', (e) => {
        if (e.target.closest('#minimizeCharacterBtn') || e.target.closest('#characterExpandPanel')) return;
        isDragging = true;
        char.classList.add('dragging');
        const rect = char.getBoundingClientRect();
        dragOffsetX = e.clientX - rect.left;
        dragOffsetY = e.clientY - rect.top;
    });
    
    document.addEventListener('mousemove', (e) => {
        if (!isDragging) return;
        const x = e.clientX - dragOffsetX;
        const y = e.clientY - dragOffsetY;
        char.style.left = x + 'px';
        char.style.top = y + 'px';
        char.style.right = 'auto';
        char.style.bottom = 'auto';
    });
    
    document.addEventListener('mouseup', () => {
        if (isDragging) {
            isDragging = false;
            char.classList.remove('dragging');
        }
    });
}

function setupCharacterInteraction() {
    const char = document.getElementById('character');
    
    char.addEventListener('click', () => {
        if (isCharacterMinimized) return;
        triggerCharacterInteraction();
    });
    
    document.getElementById('minimizeCharacterBtn').addEventListener('click', minimizeCharacter);
    document.getElementById('closeExpandPanel').addEventListener('click', expandCharacter);
    document.getElementById('expandViewAlbum').addEventListener('click', () => {
        expandCharacter();
        document.getElementById('travelAlbumModal') && document.getElementById('travelAlbumModal').classList.add('show');
    });
    document.getElementById('expandCheckin').addEventListener('click', () => {
        expandCharacter();
        showCheckinModal();
    });
}

// ==================== 热门城市卡片和宝藏推荐功能 ====================
function setupHotCitiesEvents() {
    // 热门城市卡片点击事件
    document.querySelectorAll('.hot-city-btn').forEach(btn => {
        // 地图图标点击事件 - 显示城市地图弹窗
        const mapIcon = btn.querySelector('.map-icon');
        if (mapIcon) {
            mapIcon.addEventListener('click', (e) => {
                e.stopPropagation();
                const cityId = btn.dataset.city;
                const destination = destinations.find(d => d.id === cityId);
                if (destination) {
                    showCityMapModal(destination);
                }
            });
        }
        
        // 卡片主体点击事件 - 选中城市并滚动到攻略区域
        btn.addEventListener('click', (e) => {
            if (e.target.classList.contains('map-icon')) return;
            
            const cityId = btn.dataset.city;
            const cityName = btn.dataset.cityname;
            
            // 将城市填入搜索框
            const searchInput = document.getElementById('destinationSearch');
            searchInput.value = cityName;
            
            // 标记已选中
            document.querySelectorAll('.hot-city-btn').forEach(b => b.classList.remove('selected'));
            btn.classList.add('selected');
            
            // 查找对应的目的地并选中
            const destination = destinations.find(d => d.id === cityId);
            if (destination) {
                selectDestination(destination);
            }
            
            // 滚动到攻略区域
            document.getElementById('guideSection').scrollIntoView({ behavior: 'smooth' });
        });
    });
    
    // 宝藏推荐卡片点击事件 - 弹出提交弹窗
    const treasureRecommendBtn = document.getElementById('treasureRecommendBtn');
    if (treasureRecommendBtn) {
        treasureRecommendBtn.addEventListener('click', () => {
            showRecommendModal();
        });
    }
}

function showRecommendModal() {
    const recommendModal = document.getElementById('recommendModal');
    recommendModal.classList.remove('hidden');
    recommendModal.classList.add('flex');
    setTimeout(() => {
        recommendModal.style.opacity = '1';
        const modalContent = recommendModal.querySelector('div');
        modalContent.style.transform = 'scale(1)';
    }, 10);
}

