function triggerCharacterInteraction() {
    // 随机选择动作
    const actions = ['wave', 'jump', 'heart'];
    const randomAction = actions[Math.floor(Math.random() * actions.length)];
    
    const char = document.getElementById('character');
    char.classList.add('character-action-' + randomAction);
    setTimeout(() => {
        char.classList.remove('character-action-' + randomAction);
    }, 500);
    
    // 随机选择对话
    let message;
    const rand = Math.random();
    if (rand < 0.3) {
        // 30%概率显示避坑提示
        message = avoidTips[Math.floor(Math.random() * avoidTips.length)];
    } else {
        // 70%概率显示治愈文案
        message = healingMessages[Math.floor(Math.random() * healingMessages.length)];
    }
    
    showCharacterSpeech(message, 4000);
    
    // 播放轻柔音效（如果有Audio API支持）
    if ('speechSynthesis' in window) {
        const utterance = new SpeechSynthesisUtterance(message.slice(0, 15));
        utterance.lang = 'zh-CN';
        utterance.rate = 1.2;
        utterance.volume = 0.5;
        window.speechSynthesis.speak(utterance);
    }
}

