// ==================== 选择目的地 ====================
function selectDestination(dest, btnElement) {
    document.querySelectorAll('.destination-btn').forEach(btn => {
        btn.classList.remove('selected');
    });

    if (btnElement) {
        btnElement.classList.add('selected');
    }
    selectedDestination = dest;

    updateGenerateButton();
}

// ==================== 选择选项按钮 ====================
function selectOption(type, value, btnElement) {
    const group = btnElement.closest('.option-group');
    const isAlreadySelected = btnElement.classList.contains('selected');

    group.querySelectorAll('.option-btn').forEach(btn => {
        btn.classList.remove('selected');
    });

    // 出行时段支持切换选中/取消选中
    if (type === 'travelTime') {
        if (!isAlreadySelected) {
            btnElement.classList.add('selected');
            travelTimeType = value;
        } else {
            travelTimeType = null;
        }
    } else {
        btnElement.classList.add('selected');
        selectedOptions[type] = value;
    }
}

// ==================== 应用模板 ====================
function applyTemplate(templateKey) {
    const template = templates[templateKey];
    if (!template) return;

    Object.keys(template).forEach(type => {
        if (type === 'name') return;
        
        const value = template[type];
        const group = document.getElementById(`${type}Group`);
        if (group) {
            group.querySelectorAll('.option-btn').forEach(btn => {
                btn.classList.remove('selected');
                if (btn.dataset.value === value) {
                    btn.classList.add('selected');
                }
            });
        }
        selectedOptions[type] = value;
    });
}

