function updateGenerateButton() {
    generateBtn.disabled = !selectedDestination;
}

// ==================== 城市地图弹窗功能 ====================
function showCityMapModal(city) {
    modalCityEmoji.textContent = city.emoji;
    modalCityName.textContent = city.name;
    modalCityDesc.textContent = city.description;
    
    modalCityFeatures.innerHTML = city.features.map(f => 
        `<span class="px-3 py-1 bg-purple-100 text-purple-700 rounded-full text-sm">${f}</span>`
    ).join('');
    
    modalCityFoods.innerHTML = city.foods.map(f => 
        `<span class="px-3 py-1 bg-orange-100 text-orange-700 rounded-full text-sm">${f}</span>`
    ).join('');
    
    const introText = `${city.name}是${city.description}。这里有${city.features.slice(0, 2).join('、')}等著名景点，还有${city.foods.slice(0, 2).join('、')}等特色美食值得品尝。`;
    modalCityIntro.textContent = introText;
    
    cityMapModal.classList.remove('hidden');
    cityMapModal.classList.add('flex');
    setTimeout(() => {
        cityMapModal.style.opacity = '1';
        cityMapContent.style.transform = 'scale(1)';
    }, 10);
}

function closeCityMapModal() {
    cityMapModal.style.opacity = '0';
    cityMapContent.style.transform = 'scale(0.95)';
    setTimeout(() => {
        cityMapModal.classList.add('hidden');
        cityMapModal.classList.remove('flex');
    }, 300);
}

function setupCityMapModalEvents() {
    if (!closeCityModal || !cityMapModal) return;
    closeCityModal.addEventListener('click', closeCityMapModal);
    
    cityMapModal.addEventListener('click', (e) => {
        if (e.target === cityMapModal) {
            closeCityMapModal();
        }
    });
}

