function initCharacter() {
    // 从本地存储加载数据
    const savedData = localStorage.getItem('characterData');
    if (savedData) {
        Object.assign(characterData, JSON.parse(savedData));
    }
    
    updateCharacterDisplay();
    setupCharacterEvents();
}

function updateCharacterDisplay() {
    // 更新等级
    document.getElementById('characterLevel').textContent = characterData.level;
    
    // 更新纪念章
    const badgesContainer = document.getElementById('characterBadges');
    badgesContainer.innerHTML = '';
    characterData.badges.forEach(badge => {
        const badgeElement = document.createElement('div');
        badgeElement.className = 'badge text-2xl';
        badgeElement.textContent = badge.emoji;
        badgeElement.title = badge.name;
        badgesContainer.appendChild(badgeElement);
    });
    
    // 更新小人形象（如果有装扮）
    const character = document.getElementById('character');
    if (characterData.outfits.length > 0) {
        // 显示最新的装扮
        const latestOutfit = characterData.outfits[characterData.outfits.length - 1];
        character.textContent = latestOutfit;
    } else {
        character.textContent = '🧳';
    }
}

function setupCharacterEvents() {
    const character = document.getElementById('character');
    const characterSpeech = document.getElementById('characterSpeech');
    
    character.addEventListener('dblclick', () => {
        showTravelAlbumModal();
    });
    
    character.addEventListener('click', () => {
        if (currentAction) {
            playCharacterAction();
        } else {
            showCharacterSpeech(getRandomDialogue('greeting'));
        }
    });
    
    character.addEventListener('mouseenter', () => {
        showCharacterSpeech(getRandomDialogue('greeting'));
    });
    
    character.addEventListener('mouseleave', () => {
        hideCharacterSpeech();
    });
}

function playCharacterAction() {
    const character = document.getElementById('character');
    const action = currentAction?.emoji || '👋';
    
    character.classList.add('character-action');
    showCharacterSpeech(action + ' ' + getRandomDialogue('action'));
    
    setTimeout(() => {
        character.classList.remove('character-action');
    }, 500);
}

function showCharacterSpeech(text) {
    const speech = document.getElementById('characterSpeech');
    speech.textContent = text;
    speech.classList.remove('hidden');
    
    setTimeout(() => {
        hideCharacterSpeech();
    }, 3000);
}

function hideCharacterSpeech() {
    const speech = document.getElementById('characterSpeech');
    speech.classList.add('hidden');
}

function getRandomDialogue(type) {
    const dialogues = characterDialogues[type];
    return dialogues[Math.floor(Math.random() * dialogues.length)];
}

function unlockCityBadge(cityId) {
    const badge = cityBadges[cityId];
    if (badge && !characterData.badges.some(b => b.name === badge.name)) {
        characterData.badges.push(badge);
        characterData.experience += 10;
        checkLevelUp();
        saveCharacterData();
        updateCharacterDisplay();
        showCharacterSpeech(getRandomDialogue('newBadge'));
    }
}

function unlockCityOutfit(cityId) {
    const outfit = outfits[cityId];
    if (outfit && !characterData.outfits.includes(outfit)) {
        characterData.outfits.push(outfit);
        characterData.experience += 15;
        checkLevelUp();
        saveCharacterData();
        updateCharacterDisplay();
        showCharacterSpeech(getRandomDialogue('newOutfit'));
    }
}

function checkLevelUp() {
    const newLevel = Math.floor(characterData.experience / 50) + 1;
    if (newLevel > characterData.level) {
        characterData.level = newLevel;
        showCharacterSpeech(getRandomDialogue('levelUp'));
    }
}

function saveCharacterData() {
    localStorage.setItem('characterData', JSON.stringify(characterData));
}

function addCheckin(cityId, imageUrl, note) {
    characterData.checkins.push({
        cityId,
        cityName: cityBadges[cityId]?.name || '未知城市',
        imageUrl,
        note,
        timestamp: new Date().toISOString()
    });
    saveCharacterData();
    unlockCityOutfit(cityId);
}

function addSavedGuide(guideData) {
    characterData.savedGuides.push({
        ...guideData,
        timestamp: new Date().toISOString()
    });
    saveCharacterData();
}

