// ==================== 编辑笔记功能 ====================
let currentGuideIndex = -1;

function showEditNotesModal(index) {
    currentGuideIndex = index;
    const guide = characterData.savedGuides[index];
    
    const modal = document.getElementById('editNotesModal');
    const titleInput = document.getElementById('guideTitleInput');
    const notesInput = document.getElementById('guideNotesInput');
    const tagsInput = document.getElementById('guideTagsInput');
    
    titleInput.value = guide.title || '';
    notesInput.value = guide.notes || '';
    tagsInput.value = guide.tags ? guide.tags.join(', ') : '';
    
    modal.classList.remove('hidden');
    modal.classList.add('flex');
    setTimeout(() => {
        modal.style.opacity = '1';
        const modalContent = modal.querySelector('div');
        modalContent.style.transform = 'scale(1)';
    }, 10);
}

function closeEditNotesModal() {
    const modal = document.getElementById('editNotesModal');
    modal.style.opacity = '0';
    const modalContent = modal.querySelector('div');
    modalContent.style.transform = 'scale(0.95)';
    setTimeout(() => {
        modal.classList.add('hidden');
        modal.classList.remove('flex');
        currentGuideIndex = -1;
    }, 300);
}

function saveGuideNotes() {
    if (currentGuideIndex === -1) return;
    
    const titleInput = document.getElementById('guideTitleInput');
    const notesInput = document.getElementById('guideNotesInput');
    const tagsInput = document.getElementById('guideTagsInput');
    
    const guide = characterData.savedGuides[currentGuideIndex];
    guide.title = titleInput.value.trim() || null;
    guide.notes = notesInput.value.trim() || null;
    guide.tags = tagsInput.value.trim() ? tagsInput.value.split(',').map(tag => tag.trim()) : null;
    
    saveCharacterData();
    updateTravelAlbum();
    closeEditNotesModal();
    showToast('笔记保存成功！', 'success');
}

