let currentQuestionIndex = 0;
let personalityAnswers = [];
let userPersonality = null;

function showPersonalityTestModal() {
    const modal = document.getElementById('personalityTestModal');
    modal.classList.remove('hidden');
    modal.classList.add('flex');
    setTimeout(() => {
        modal.style.opacity = '1';
        const modalContent = modal.querySelector('div');
        modalContent.style.transform = 'scale(1)';
    }, 10);
    resetPersonalityTest();
    updateQuestion();
}

function closePersonalityTestModal() {
    const modal = document.getElementById('personalityTestModal');
    modal.style.opacity = '0';
    const modalContent = modal.querySelector('div');
    modalContent.style.transform = 'scale(0.95)';
    setTimeout(() => {
        modal.classList.add('hidden');
        modal.classList.remove('flex');
    }, 300);
}

function resetPersonalityTest() {
    currentQuestionIndex = 0;
    personalityAnswers = [];
    userPersonality = null;
    document.getElementById('personalityTestContent').classList.remove('hidden');
    document.getElementById('personalityResult').classList.add('hidden');
    updateQuestion();
}

function updateQuestion() {
    const question = personalityTestQuestions[currentQuestionIndex];
    document.getElementById('currentQuestion').textContent = currentQuestionIndex + 1;
    document.getElementById('questionText').textContent = question.question;
    
    const optionsContainer = document.getElementById('optionsContainer');
    optionsContainer.innerHTML = '';
    
    question.options.forEach((option, index) => {
        const btn = document.createElement('button');
        btn.className = 'option-btn w-full text-left p-4 border border-gray-300 rounded-xl hover:bg-gray-50 transition-colors';
        btn.dataset.value = String.fromCharCode(65 + index);
        btn.innerHTML = option;
        
        // 恢复之前的选择
        if (personalityAnswers[currentQuestionIndex] === btn.dataset.value) {
            btn.classList.add('selected');
        }
        
        btn.addEventListener('click', () => {
            // 移除其他选项的选中状态
            optionsContainer.querySelectorAll('.option-btn').forEach(b => b.classList.remove('selected'));
            // 添加当前选项的选中状态
            btn.classList.add('selected');
            // 保存答案
            personalityAnswers[currentQuestionIndex] = btn.dataset.value;
        });
        
        optionsContainer.appendChild(btn);
    });
    
    // 更新进度条
    const progress = ((currentQuestionIndex + 1) / personalityTestQuestions.length) * 100;
    document.getElementById('progressBar').style.width = `${progress}%`;
    document.getElementById('progressText').textContent = `${Math.round(progress)}%`;
    
    // 更新导航按钮状态
    document.getElementById('prevQuestionBtn').disabled = currentQuestionIndex === 0;
    document.getElementById('nextQuestionBtn').textContent = currentQuestionIndex === personalityTestQuestions.length - 1 ? '查看结果' : '下一题';
}

function nextQuestion() {
    // 检查是否已选择答案
    if (!personalityAnswers[currentQuestionIndex]) {
        alert('请选择一个答案');
        return;
    }
    
    if (currentQuestionIndex < personalityTestQuestions.length - 1) {
        currentQuestionIndex++;
        updateQuestion();
    } else {
        calculatePersonality();
        showPersonalityResult();
    }
}

function prevQuestion() {
    if (currentQuestionIndex > 0) {
        currentQuestionIndex--;
        updateQuestion();
    }
}

function calculatePersonality() {
    // 统计各选项的数量
    const counts = { A: 0, B: 0, C: 0, D: 0 };
    personalityAnswers.forEach(answer => {
        counts[answer]++;
    });
    
    // 找出出现次数最多的选项
    let maxCount = 0;
    let dominantPersonality = 'A';
    
    for (const [key, count] of Object.entries(counts)) {
        if (count > maxCount) {
            maxCount = count;
            dominantPersonality = key;
        }
    }
    
    userPersonality = personalityTypes[dominantPersonality];
}

function showPersonalityResult() {
    document.getElementById('personalityTestContent').classList.add('hidden');
    document.getElementById('personalityResult').classList.remove('hidden');
    
    document.getElementById('personalityEmoji').textContent = userPersonality.emoji;
    document.getElementById('personalityTitle').textContent = userPersonality.type;
    document.getElementById('personalityDescription').textContent = userPersonality.description;
}

function startPlanningWithPersonality() {
    closePersonalityTestModal();
    if (userPersonality && userPersonality.emoji) {
        userProfile.avatar = userPersonality.emoji;
        localStorage.setItem('userProfile', JSON.stringify(userProfile));
    }
    updateCharacterAppearance();
}

function setupPersonalityTestEvents() {
    const modal = document.getElementById('personalityTestModal');
    const closeBtn = document.getElementById('closePersonalityTestModal');
    const nextBtn = document.getElementById('nextQuestionBtn');
    const prevBtn = document.getElementById('prevQuestionBtn');
    const startPlanningBtn = document.getElementById('startPlanningBtn');
    
    closeBtn.addEventListener('click', closePersonalityTestModal);
    nextBtn.addEventListener('click', nextQuestion);
    prevBtn.addEventListener('click', prevQuestion);
    startPlanningBtn.addEventListener('click', startPlanningWithPersonality);
    
    modal.addEventListener('click', (e) => {
        if (e.target === modal) {
            closePersonalityTestModal();
        }
    });
}

