function generateGuideImage() {
    if (!selectedDestination) {
        showToast('请先生成攻略～', 'warning');
        return;
    }
    
    showToast('正在生成攻略图片...', 'info');
    
    // 模拟生成图片的过程
    setTimeout(() => {
        // 创建一个简单的图片预览
        const imagePreview = document.createElement('div');
        imagePreview.className = 'fixed top-1/2 left-1/2 transform -translate-x-1/2 -translate-y-1/2 z-50 bg-white rounded-2xl shadow-2xl p-6 max-w-md w-full mx-4';
        
        imagePreview.innerHTML = `
            <div class="flex justify-between items-center mb-4">
                <h3 class="text-lg font-bold text-gray-700">攻略图片</h3>
                <button class="close-image-preview text-gray-400 hover:text-gray-600 transition-colors">
                    <span class="text-xl">✕</span>
                </button>
            </div>
            <div class="bg-gradient-to-r from-pink-400 via-purple-400 to-blue-400 rounded-xl p-4 text-white text-center mb-4">
                <h4 class="text-xl font-bold mb-2">${selectedDestination.name}旅行攻略</h4>
                <p class="text-sm opacity-90">${selectedOptions.days}天${selectedOptions.days - 1}晚 · 专属定制</p>
            </div>
            <div class="space-y-2 mb-4">
                <div class="flex items-center gap-2">
                    <span class="text-pink-500">🌟</span>
                    <span class="text-sm text-gray-600">核心景点：${selectedDestination.features.slice(0, 3).join('、')}</span>
                </div>
                <div class="flex items-center gap-2">
                    <span class="text-orange-500">🍜</span>
                    <span class="text-sm text-gray-600">特色美食：${selectedDestination.foods.slice(0, 3).join('、')}</span>
                </div>
                <div class="flex items-center gap-2">
                    <span class="text-blue-500">🏨</span>
                    <span class="text-sm text-gray-600">推荐住宿：${selectedDestination.hotels[0].name}</span>
                </div>
            </div>
            <button class="download-image-btn w-full py-2 bg-gradient-to-r from-green-400 to-teal-400 text-white font-bold rounded-full shadow-md hover:shadow-lg transition-all duration-300">
                下载图片
            </button>
        `;
        
        document.body.appendChild(imagePreview);
        
        // 关闭按钮事件
        const closeBtn = imagePreview.querySelector('.close-image-preview');
        closeBtn.addEventListener('click', () => {
            imagePreview.remove();
        });
        
        // 下载按钮事件
        const downloadBtn = imagePreview.querySelector('.download-image-btn');
        downloadBtn.addEventListener('click', () => {
            showToast('图片已下载到本地', 'success');
            imagePreview.remove();
        });
        
        showToast('攻略图片生成成功！', 'success');
    }, 1500);
}

