// ==================== 设置事件监听器 ====================
function setupEventListeners() {
    // 目的地搜索框事件 - 高亮匹配的热门城市并显示搜索结果
    const destinationSearch = document.getElementById('destinationSearch');
    if (!destinationSearch) return;
    destinationSearch.addEventListener('input', (e) => {
        destinationSearchQuery = e.target.value.trim().toLowerCase();
        
        // 清空搜索时，重置所有卡片的选中状态
        if (destinationSearchQuery === '') {
            document.querySelectorAll('.hot-city-btn').forEach(btn => {
                btn.classList.remove('highlight');
                btn.classList.remove('selected');
            });
        } else {
            // 高亮匹配的热门城市
            document.querySelectorAll('.hot-city-btn').forEach(btn => {
                const cityName = btn.dataset.cityname.toLowerCase();
                if (cityName.includes(destinationSearchQuery)) {
                    btn.classList.add('highlight');
                } else {
                    btn.classList.remove('highlight');
                }
            });
        }
        
        // 显示搜索结果
        if (destinationSearchQuery) {
            searchDestinations(destinationSearchQuery);
        } else {
            // 清空搜索结果
            document.getElementById('searchResults').classList.add('hidden');
            document.getElementById('noDestinationResult').classList.add('hidden');
        }
    });

    // 选项按钮点击事件
    document.querySelectorAll('.option-btn').forEach(btn => {
        btn.addEventListener('click', () => {
            const type = btn.dataset.type;
            const value = btn.dataset.value;
            selectOption(type, value, btn);
        });
    });

    // 模板按钮点击事件
    document.querySelectorAll('.template-btn').forEach(btn => {
        btn.addEventListener('click', () => {
            const templateKey = btn.dataset.template;
            applyTemplate(templateKey);
            
            btn.style.transform = 'scale(0.95)';
            setTimeout(() => {
                btn.style.transform = '';
            }, 150);
        });
    });

    // 生成攻略按钮点击事件
    if (generateBtn) generateBtn.addEventListener('click', generateGuide);

    // 旅行人格测试按钮点击事件 - 已禁用
    // const personalityTestBtn = document.getElementById('personalityTestBtn');
    // if (personalityTestBtn) personalityTestBtn.addEventListener('click', showPersonalityTestModal);

    // 重新生成按钮点击事件
    if (regenerateBtn) {
        regenerateBtn.addEventListener('click', () => {
            if (guideSection) guideSection.classList.add('hidden');
            document.querySelectorAll('section').forEach(s => s.classList.remove('hidden'));
            document.querySelectorAll('.max-w-4xl, .max-w-5xl').forEach(el => {
                if (!el.closest('#guideSection')) {
                    el.classList.remove('hidden');
                }
            });
            window.scrollTo({ top: 0, behavior: 'smooth' });
        });
    }

    // 方案标签页切换
    document.querySelectorAll('.plan-tab').forEach(tab => {
        tab.addEventListener('click', () => {
            const plan = tab.dataset.plan;
            switchPlanTab(plan);
        });
    });

    // 收藏按钮点击事件
    const favoriteBtn = document.getElementById('favoriteBtn');
    if (favoriteBtn) {
        favoriteBtn.addEventListener('click', function(e) {
            // 按钮动画反馈
            this.style.transform = 'scale(0.95)';
            setTimeout(() => {
                this.style.transform = '';
            }, 150);
            toggleFavorite();
        });
    }

    // 复制按钮点击事件
    const copyBtn = document.getElementById('copyBtn');
    if (copyBtn) {
        copyBtn.addEventListener('click', function(e) {
            // 按钮动画反馈
            this.style.transform = 'scale(0.95)';
            setTimeout(() => {
                this.style.transform = '';
            }, 150);
            copyGuideToClipboard();
        });
    }

    // 分享按钮点击事件
    const shareBtn = document.getElementById('shareBtn');
    if (shareBtn) {
        shareBtn.addEventListener('click', function(e) {
            // 按钮动画反馈
            this.style.transform = 'scale(0.95)';
            setTimeout(() => {
                this.style.transform = '';
            }, 150);
            shareGuide();
        });
    }

    // 新增功能按钮事件
    const backToOptionsBtn = document.getElementById('backToOptionsBtn');
    const toggleGuideBtn = document.getElementById('toggleGuideBtn');
    const clearGuideBtn = document.getElementById('clearGuideBtn');
    if (backToOptionsBtn) backToOptionsBtn.addEventListener('click', backToOptions);
    if (toggleGuideBtn) toggleGuideBtn.addEventListener('click', toggleGuide);
    if (clearGuideBtn) clearGuideBtn.addEventListener('click', clearGuide);
    
    // 修改攻略按钮事件
    const editGuideBtn = document.getElementById('editGuideBtn');
    if (editGuideBtn) {
        editGuideBtn.addEventListener('click', function(e) {
            // 按钮动画反馈
            this.style.transform = 'scale(0.95)';
            setTimeout(() => {
                this.style.transform = '';
            }, 150);
            
            // 隐藏攻略部分
            if (guideSection) guideSection.classList.add('hidden');
            
            // 显示所有其他部分
            document.querySelectorAll('section:not(#guideSection)').forEach(s => s.classList.remove('hidden'));
            document.querySelectorAll('.max-w-4xl, .max-w-5xl').forEach(el => {
                if (!el.closest('#guideSection')) {
                    el.classList.remove('hidden');
                }
            });
            const titleSection = document.querySelector('.text-center.mb-12');
            if (titleSection) titleSection.classList.remove('hidden');
            
            // 滚动到偏好选择区
            window.scrollTo({ 
                top: 300, 
                behavior: 'smooth' 
            });
            
            // 显示提示
            showToast('请修改偏好后重新生成攻略', 'info');
        });
    }

    // 旅行备忘录事件
    setupMemoListeners();

    // 城市地图弹窗事件
    setupCityMapModalEvents();

    // 推荐目的地弹窗事件
    setupRecommendModalEvents();

    // 旅行人格测试弹窗事件
    setupPersonalityTestEvents();

    // 旅行纪念册弹窗事件
    setupTravelAlbumEvents();

    // 分享菜单弹窗事件
    setupShareMenuEvents();

    // 反馈成功弹窗事件
    setupFeedbackModalEvents();
}

// ==================== 搜索目的地 ====================
function searchDestinations(query) {
    const searchResultsGrid = document.getElementById('searchResultsGrid');
    const searchResults = document.getElementById('searchResults');
    const noResult = document.getElementById('noDestinationResult');
    
    if (!searchResultsGrid || !searchResults || !noResult) return;
    
    // 搜索destinations数组
    const matchedDestinations = destinations.filter(dest => 
        dest.name.toLowerCase().includes(query) ||
        dest.description.toLowerCase().includes(query) ||
        dest.features.some(feature => feature.toLowerCase().includes(query))
    );
    
    // 搜索destinationDatabase数组
    const matchedDatabase = destinationDatabase.filter(dest => 
        dest.name.toLowerCase().includes(query) ||
        dest.description.toLowerCase().includes(query) ||
        dest.features.some(feature => feature.toLowerCase().includes(query))
    );
    
    // 合并结果并去重
    const allResults = [...matchedDestinations];
    const existingIds = new Set(matchedDestinations.map(d => d.id));
    
    matchedDatabase.forEach(dest => {
        if (!existingIds.has(dest.id)) {
            allResults.push(dest);
            existingIds.add(dest.id);
        }
    });
    
    if (allResults.length === 0) {
        searchResults.classList.add('hidden');
        noResult.classList.remove('hidden');
        return;
    }
    
    searchResults.classList.remove('hidden');
    noResult.classList.add('hidden');
    searchResultsGrid.innerHTML = '';
    
    allResults.forEach((dest, index) => {
        const btn = document.createElement('button');
        btn.className = 'destination-btn search-result-btn flex flex-col items-center p-4 rounded-2xl bg-gradient-to-br from-purple-50 to-pink-50 shadow-lg hover:shadow-xl transition-all duration-300 border-2 border-purple-200';
        btn.dataset.id = dest.id;
        btn.style.animationDelay = `${index * 0.1}s`;
        
        btn.innerHTML = `
            <span class="emoji text-4xl mb-2 transition-transform duration-300">${dest.emoji}</span>
            <span class="font-semibold text-gray-700">${dest.name}</span>
            <span class="text-xs text-gray-400 mt-1">${dest.description}</span>
        `;
        
        btn.addEventListener('click', () => {
            // 查找对应的目的地并选中
            const destination = destinations.find(d => d.id === dest.id) || dest;
            if (destination) {
                selectDestination(destination);
                
                // 将城市填入搜索框
                const searchInput = document.getElementById('destinationSearch');
                if (searchInput) searchInput.value = dest.name;
                
                // 标记热门城市为选中状态
                document.querySelectorAll('.hot-city-btn').forEach(b => {
                    if (b.dataset.city === dest.id) {
                        b.classList.add('selected');
                    } else {
                        b.classList.remove('selected');
                    }
                });
                
                // 滚动到攻略区域
                const guideSection = document.getElementById('guideSection');
                if (guideSection) guideSection.scrollIntoView({ behavior: 'smooth' });
            }
        });
        
        searchResultsGrid.appendChild(btn);
    });
}

// ==================== 切换方案标签页 ====================
function switchPlanTab(plan) {
    currentPlanTab = plan;
    
    document.querySelectorAll('.plan-tab').forEach(tab => {
        if (tab.dataset.plan === plan) {
            tab.classList.add('active');
            tab.classList.add('bg-gradient-to-r', 'from-pink-400', 'to-purple-400', 'text-white');
            tab.classList.remove('text-gray-600');
        } else {
            tab.classList.remove('active', 'bg-gradient-to-r', 'from-pink-400', 'to-purple-400', 'text-white');
            tab.classList.add('text-gray-600');
        }
    });

    if (plan === 'compact') {
        planA.classList.remove('hidden');
        planB.classList.add('hidden');
    } else {
        planA.classList.add('hidden');
        planB.classList.remove('hidden');
    }
}

