function renderLocalTips() {
    const dest = selectedDestination;
    const tipsData = localTipsData[dest.id];
    
    if (!tipsData) return;
    
    // 渲染网红店红黑榜
    const redBlackList = document.getElementById('redBlackList');
    redBlackList.innerHTML = '';
    
    // 红榜
    const redList = document.createElement('div');
    redList.className = 'bg-green-50 rounded-xl p-4 border-2 border-green-200';
    redList.innerHTML = `
        <h5 class="font-semibold text-green-700 mb-3 flex items-center gap-2">
            <span>✅</span> 红榜（推荐）
        </h5>
        <div class="space-y-3">
            ${tipsData.redBlackList.red.map(item => `
                <div class="flex items-start gap-2">
                    <span class="text-green-500 mt-1">•</span>
                    <div>
                        <div class="font-medium">${item.name}</div>
                        <div class="text-sm text-gray-600">${item.reason}</div>
                        <div class="text-sm text-yellow-500">⭐ ${item.rating}</div>
                    </div>
                </div>
            `).join('')}
        </div>
    `;
    redBlackList.appendChild(redList);
    
    // 黑榜
    const blackList = document.createElement('div');
    blackList.className = 'bg-red-50 rounded-xl p-4 border-2 border-red-200';
    blackList.innerHTML = `
        <h5 class="font-semibold text-red-700 mb-3 flex items-center gap-2">
            <span>❌</span> 黑榜（避坑）
        </h5>
        <div class="space-y-3">
            ${tipsData.redBlackList.black.map(item => `
                <div class="flex items-start gap-2">
                    <span class="text-red-500 mt-1">•</span>
                    <div>
                        <div class="font-medium">${item.name}</div>
                        <div class="text-sm text-gray-600">${item.reason}</div>
                        <div class="text-sm text-yellow-500">⭐ ${item.rating}</div>
                    </div>
                </div>
            `).join('')}
        </div>
    `;
    redBlackList.appendChild(blackList);
    
    // 渲染景点免费平替
    const freeAlternatives = document.getElementById('freeAlternatives');
    freeAlternatives.innerHTML = '';
    
    tipsData.freeAlternatives.forEach(item => {
        const alternative = document.createElement('div');
        alternative.className = 'bg-blue-50 rounded-xl p-4 border-2 border-blue-200';
        alternative.innerHTML = `
            <div class="flex flex-col md:flex-row md:items-center justify-between gap-2">
                <div>
                    <div class="font-medium text-blue-700">${item.paid}</div>
                    <div class="text-sm text-gray-600">→ ${item.free}</div>
                </div>
                <div class="text-sm text-gray-600">${item.reason}</div>
            </div>
        `;
        freeAlternatives.appendChild(alternative);
    });
    
    // 渲染错峰出行时间轴
    const offPeakTimeline = document.getElementById('offPeakTimeline');
    offPeakTimeline.innerHTML = '';
    
    tipsData.offPeakTimeline.forEach((item, index) => {
        const timelineItem = document.createElement('div');
        timelineItem.className = 'flex gap-4';
        timelineItem.innerHTML = `
            <div class="flex flex-col items-center">
                <div class="w-8 h-8 rounded-full bg-purple-500 text-white flex items-center justify-center text-sm font-bold">${index + 1}</div>
                ${index < tipsData.offPeakTimeline.length - 1 ? '<div class="w-0.5 h-full bg-purple-200"></div>' : ''}
            </div>
            <div class="flex-1 pb-6">
                <div class="font-semibold text-purple-700">${item.time}</div>
                <div class="text-sm text-gray-600 mt-1">📍 ${item.spots}</div>
                <div class="text-sm text-gray-600 mt-1">💡 ${item.tip}</div>
            </div>
        `;
        offPeakTimeline.appendChild(timelineItem);
    });
    
    // 渲染消费防套路提示
    const antiScamTips = document.getElementById('antiScamTips');
    antiScamTips.innerHTML = '';
    
    tipsData.antiScamTips.forEach(tip => {
        const tipItem = document.createElement('div');
        tipItem.className = 'flex items-start gap-2 bg-yellow-50 p-3 rounded-xl border-2 border-yellow-200';
        tipItem.innerHTML = `
            <span class="text-yellow-500 mt-0.5">⚠️</span>
            <span class="text-sm text-gray-700">${tip}</span>
        `;
        antiScamTips.appendChild(tipItem);
    });
}

// ==================== 渲染攻略内容 ====================
function renderGuide() {
    const dest = selectedDestination;
    const days = parseInt(selectedOptions.days);

    const crowdNames = {
        solo: '独自旅行',
        couple: '甜蜜情侣',
        family: '亲子家庭',
        friends: '闺蜜好友',
        team: '团队出行'
    };

    // 设置攻略标题和副标题
    guideTitle.innerHTML = `${dest.emoji} ${dest.name}旅行攻略 ${dest.emoji}`;
    guideSubtitle.textContent = `${days}天${days - 1}晚 · ${crowdNames[selectedOptions.crowd]} · 专属定制 ✨`;

    // 生成智能出行标签
    generateSmartTags(dest, selectedOptions);

    // 渲染各个板块
    try {
        renderCities();
        renderPlans();
        renderTransport();
        renderFoods();
        renderHotels();
        renderAvoid();
        renderTips();
        renderBudget();
        renderLocalTips();
        updateFavoriteButton();
    } catch (error) {
        console.error('渲染攻略内容失败:', error);
        throw error;
    }
    
    // 保存攻略到本地存储
    saveGuideToLocalStorage();
}

// ==================== 保存攻略到本地存储 ====================
function saveGuideToLocalStorage() {
    try {
        const guideData = {
            destination: selectedDestination,
            options: selectedOptions,
            personality: userPersonality,
            generatedAt: new Date().toISOString()
        };
        
        // 保存当前攻略
        localStorage.setItem('currentGuide', JSON.stringify(guideData));
        
        // 保存历史攻略
        const history = JSON.parse(localStorage.getItem('guideHistory') || '[]');
        history.unshift(guideData);
        // 只保留最近10条
        const limitedHistory = history.slice(0, 10);
        localStorage.setItem('guideHistory', JSON.stringify(limitedHistory));
        
        console.log('攻略已保存到本地存储');
    } catch (err) {
        console.error('保存攻略失败:', err);
    }
}

// ==================== 渲染推荐城市 ====================
function renderCities() {
    if (!cityCards) return;
    cityCards.innerHTML = '';
    
    // 随机选择3个推荐城市（包含选中城市 + 2个其他城市）
    const otherCities = destinations.filter(d => d.id !== selectedDestination.id);
    const shuffled = otherCities.sort(() => Math.random() - 0.5).slice(0, 2);
    const recommendedCities = [selectedDestination, ...shuffled].sort(() => Math.random() - 0.5);

    recommendedCities.forEach((city, index) => {
        const card = document.createElement('div');
        card.className = 'city-card fade-in';
        card.style.animationDelay = `${index * 0.15}s`;
        
        card.innerHTML = `
            <div class="city-emoji">${city.emoji}</div>
            <div class="city-name">${city.name}</div>
            <div class="city-desc">${city.description}</div>
        `;
        
        card.addEventListener('click', () => {
            document.querySelectorAll('.destination-btn').forEach(btn => {
                if (btn.dataset.id === city.id) {
                    btn.click();
                    window.scrollTo({ top: 300, behavior: 'smooth' });
                }
            });
        });
        
        cityCards.appendChild(card);
    });
}

// ==================== 显示城市地图详情 ====================
function showCityMap(cityId) {
    const city = destinations.find(c => c.id === cityId);
    if (!city) return;
    
    // 创建城市地图卡片
    const mapCard = document.createElement('div');
    mapCard.className = 'city-map-card fixed z-50 bg-white rounded-2xl shadow-2xl p-6 max-w-md w-full mx-4 transform scale-95 transition-transform duration-300';
    mapCard.style.top = '50%';
    mapCard.style.left = '50%';
    mapCard.style.transform = 'translate(-50%, -50%) scale(0.95)';
    mapCard.style.opacity = '0';
    mapCard.style.transition = 'all 0.3s ease';
    
    mapCard.innerHTML = `
        <div class="flex justify-between items-start mb-4">
            <div class="flex items-center gap-3">
                <div class="text-4xl">${city.emoji}</div>
                <div>
                    <h3 class="text-xl font-bold text-gray-800">${city.name}</h3>
                    <p class="text-sm text-gray-500">${city.description}</p>
                </div>
            </div>
            <button class="close-map-btn text-gray-400 hover:text-gray-600 transition-colors">
                <span class="text-xl">✕</span>
            </button>
        </div>
        
        <div class="space-y-4">
            <div>
                <h4 class="font-semibold text-gray-700 mb-2 flex items-center gap-2">
                    <span>🌟</span> 核心景点
                </h4>
                <ul class="space-y-2">
                    ${city.features.map(feature => `<li class="flex items-center gap-2 text-sm text-gray-600">
                        <span class="text-pink-500">📍</span>
                        <span>${feature}</span>
                    </li>`).join('')}
                </ul>
            </div>
            
            <div>
                <h4 class="font-semibold text-gray-700 mb-2 flex items-center gap-2">
                    <span>🍜</span> 特色美食
                </h4>
                <ul class="space-y-2">
                    ${city.foods.map(food => `<li class="flex items-center gap-2 text-sm text-gray-600">
                        <span class="text-orange-500">🍽️</span>
                        <span>${food}</span>
                    </li>`).join('')}
                </ul>
            </div>
            
            <div>
                <h4 class="font-semibold text-gray-700 mb-2 flex items-center gap-2">
                    <span>💡</span> 旅行小贴士
                </h4>
                <ul class="space-y-2">
                    ${city.avoidTips.slice(0, 3).map(tip => `<li class="flex items-start gap-2 text-sm text-gray-600">
                        <span class="text-yellow-500 mt-0.5">⚠️</span>
                        <span>${tip.content}</span>
                    </li>`).join('')}
                </ul>
            </div>
        </div>
    `;
    
    // 创建遮罩层
    const overlay = document.createElement('div');
    overlay.className = 'fixed inset-0 bg-black/50 backdrop-blur-sm z-40';
    
    document.body.appendChild(overlay);
    document.body.appendChild(mapCard);
    
    // 动画效果
    setTimeout(() => {
        mapCard.style.transform = 'translate(-50%, -50%) scale(1)';
        mapCard.style.opacity = '1';
    }, 10);
    
    // 关闭按钮事件
    const closeBtn = mapCard.querySelector('.close-map-btn');
    closeBtn.addEventListener('click', () => closeCityMap(mapCard, overlay));
    
    // 点击遮罩层关闭
    overlay.addEventListener('click', () => closeCityMap(mapCard, overlay));
}

// ==================== 关闭城市地图详情 ====================
function closeCityMap(mapCard, overlay) {
    mapCard.style.transform = 'translate(-50%, -50%) scale(0.95)';
    mapCard.style.opacity = '0';
    
    setTimeout(() => {
        if (mapCard.parentNode) mapCard.parentNode.removeChild(mapCard);
        if (overlay.parentNode) overlay.parentNode.removeChild(overlay);
    }, 300);
}

// ==================== 渲染双方案行程 ====================
function renderPlans() {
    if (!planAContent || !planBContent) return;
    // 方案A：紧凑高效版
    planAContent.innerHTML = renderCompactPlan();
    
    // 方案B：佛系懒人版
    planBContent.innerHTML = renderRelaxedPlan();
    
    // 重置标签页状态
    switchPlanTab('compact');
}

// ==================== 渲染紧凑方案 ====================
