// ==================== 获取交通数据 ====================
function getTransportData() {
    const transport = selectedOptions.transport;
    const dest = selectedDestination;
    
    const transportMap = {
        train: [
            { icon: '🚄', title: '高铁出行', desc: `到达${dest.name}站后，可乘坐地铁或公交前往市区` },
            { icon: '🚇', title: '市内交通', desc: '地铁+公交组合最便捷，建议办理交通卡' },
            { icon: '🚶', title: '景区间交通', desc: '景点间步行+短途打车最省时' }
        ],
        car: [
            { icon: '🚗', title: '自驾前往', desc: `导航至${dest.name}，沿途风景优美` },
            { icon: '🅿️', title: '停车攻略', desc: '景区周边停车场步行可达，记得早出发' },
            { icon: '🚘', title: '出行建议', desc: '古城区域建议步行进入，避免交通管制' }
        ],
        walk: [
            { icon: '🚶', title: '步行漫游', desc: `${dest.name}适合慢节奏游览，放慢脚步感受城市魅力` },
            { icon: '🚲', title: '骑行推荐', desc: '租借共享单车，穿梭大街小巷' },
            { icon: '🚌', title: '公交出行', desc: '随时可以乘坐公交休息，省时省力' }
        ]
    };
    
    return transportMap[transport] || transportMap.walk;
}

