// ==================== 渲染预算估算 ====================
function renderBudget() {
    if (!budgetContent) return;
    budgetContent.innerHTML = '';
    const days = parseInt(selectedOptions.days);
    const budget = selectedOptions.budget;
    const crowd = selectedOptions.crowd;
    const travelTime = travelTimeType; // 使用全局变量
    const dest = selectedDestination;
    
    // 根据人数计算
    const personCount = { solo: 1, couple: 2, family: 3, friends: 4, team: 10 }[crowd];
    
    // 基础预算配置
    const budgetConfig = {
        budget: { transport: 150, other: 50 },
        normal: { transport: 300, other: 100 },
        luxury: { transport: 600, other: 200 }
    };
    
    const config = budgetConfig[budget];
    
    // 获取酒店价格（根据出行时段）【人工采集静态固化数据，非AI生成】
    const hotelPrice = dest.hotels && dest.hotels.length > 0 && dest.hotels[0].price ? 
        dest.hotels[0].price[travelTime] : 
        (budget === 'budget' ? 150 : budget === 'normal' ? 300 : 600);
    
    // 获取餐饮价格（根据出行时段）【人工采集静态固化数据，非AI生成】
    const foodPrice = dest.foodPrices && dest.foodPrices[travelTime] ? 
        Math.round(dest.foodPrices[travelTime].reduce((a, b) => a + b, 0) / dest.foodPrices[travelTime].length) : 
        (budget === 'budget' ? 80 : budget === 'normal' ? 150 : 300);
    
    const items = [
        { icon: '🚗', name: '交通费', value: config.transport * days * (crowd === 'team' ? 0.3 : 1) },
        { icon: '🏨', name: '住宿费', value: hotelPrice * days * Math.ceil(personCount / 2) },
        { icon: '🍜', name: '餐饮费', value: foodPrice * days * personCount },
        { icon: '🎫', name: '门票费', value: 100 * days * personCount },
        { icon: '🛍️', name: '其他费用', value: config.other * days * personCount }
    ];
    
    items.forEach((item, index) => {
        const div = document.createElement('div');
        div.className = 'budget-item fade-in';
        div.style.animationDelay = `${index * 0.08}s`;
        
        div.innerHTML = `
            <div class="budget-label">
                <span class="budget-icon">${item.icon}</span>
                <span class="budget-name">${item.name}</span>
            </div>
            <span class="budget-value">¥${item.value.toLocaleString()}</span>
        `;
        
        budgetContent.appendChild(div);
    });
    
    // 总计
    const total = items.reduce((sum, item) => sum + item.value, 0);
    const totalDiv = document.createElement('div');
    totalDiv.className = 'budget-item budget-total fade-in';
    totalDiv.style.animationDelay = `${items.length * 0.08}s`;
    
    totalDiv.innerHTML = `
        <div class="budget-label">
            <span class="budget-icon">💰</span>
            <span class="budget-name">总预算估算</span>
        </div>
        <span class="budget-value">¥${total.toLocaleString()}</span>
    `;
    
    budgetContent.appendChild(totalDiv);
}

// ==================== 宝藏推荐功能 ====================
const RECOMMENDS_KEY = 'travelPlannerRecommends';
let recommends = JSON.parse(localStorage.getItem(RECOMMENDS_KEY)) || [];

const cityEmojis = ['🏙️', '🌆', '🏯', '🏔️', '🌊', '🌸', '🍃', '🦋', '🌅', '🏞️', '🗼', '🗾', '🌴', '🎭', '🏛️'];

function loadRecommends() {
    renderRecommendsList();
    setupRecommendEvents();
}

function saveRecommends() {
    localStorage.setItem(RECOMMENDS_KEY, JSON.stringify(recommends));
}

function setupRecommendEvents() {
    const submitBtn = document.getElementById('submitRecommend');
    const cityInput = document.getElementById('recommendCity');
    const reasonInput = document.getElementById('recommendReason');

    submitBtn.addEventListener('click', addRecommend);

    cityInput.addEventListener('keypress', (e) => {
        if (e.key === 'Enter') reasonInput.focus();
    });

    reasonInput.addEventListener('keypress', (e) => {
        if (e.key === 'Enter') addRecommend();
    });
}

function addRecommend() {
    const cityInput = document.getElementById('recommendCity');
    const reasonInput = document.getElementById('recommendReason');
    
    const city = cityInput.value.trim();
    const reason = reasonInput.value.trim();

    if (!city) {
        showToast('请输入城市名称～', 'warning');
        cityInput.focus();
        return;
    }

    if (!reason) {
        showToast('请输入推荐理由～', 'warning');
        reasonInput.focus();
        return;
    }

    const randomEmoji = cityEmojis[Math.floor(Math.random() * cityEmojis.length)];
    
    const newRecommend = {
        id: Date.now(),
        city: city,
        emoji: randomEmoji,
        reason: reason,
        timestamp: new Date().toLocaleDateString('zh-CN', { month: 'short', day: 'numeric' })
    };

    recommends.unshift(newRecommend);
    saveRecommends();
    renderRecommendsList(true, newRecommend.id);

    cityInput.value = '';
    reasonInput.value = '';
    cityInput.focus();

    showToast(`${city} 推荐成功！`, 'success');
}

function renderRecommendsList(isNew = false, newId = null) {
    const recommendList = document.getElementById('recommendList');
    const noRecommends = document.getElementById('noRecommends');

    if (recommends.length === 0) {
        recommendList.innerHTML = '';
        noRecommends.classList.remove('hidden');
        return;
    }

    noRecommends.classList.add('hidden');
    recommendList.innerHTML = '';

    recommends.forEach((rec, index) => {
        const div = document.createElement('div');
        div.className = 'recommend-card';
        
        if (isNew && rec.id === newId) {
            div.style.animationDelay = '0s';
        } else {
            div.style.animationDelay = `${Math.min(index * 0.05, 0.3)}s`;
            div.style.opacity = '0';
            setTimeout(() => {
                div.style.opacity = '1';
            }, 50);
        }

        div.innerHTML = `
            <div class="card-header">
                <div class="city-name">
                    <span class="city-emoji">${rec.emoji}</span>
                    <span>${rec.city}</span>
                </div>
                <button class="delete-btn" onclick="deleteRecommend(${index})" title="删除">✕</button>
            </div>
            <p class="reason">"${rec.reason}"</p>
            <p class="timestamp">${rec.timestamp}</p>
        `;

        recommendList.appendChild(div);
    });
}

function deleteRecommend(index) {
    recommends.splice(index, 1);
    saveRecommends();
    renderRecommendsList();
    showToast('已删除推荐', 'info');
}

// ==================== 反馈功能 ====================
const FEEDBACKS_KEY = 'travelPlannerFeedbacks';
const RATING_KEY = 'travelPlannerCurrentRating';
let feedbacks = JSON.parse(localStorage.getItem(FEEDBACKS_KEY)) || [];
let currentRating = parseInt(localStorage.getItem(RATING_KEY)) || 0;

const ratingTexts = {
    1: '还需努力',
    2: '可以更好',
    3: '还不错',
    4: '很棒！',
    5: '太完美了！'
};

function loadFeedbacks() {
    renderFeedbacksList();
    setupFeedbackEvents();
}

function saveFeedbacks() {
    localStorage.setItem(FEEDBACKS_KEY, JSON.stringify(feedbacks));
}

function setupFeedbackEvents() {
    const stars = document.querySelectorAll('.star');
    const submitBtn = document.getElementById('submitFeedback');
    const feedbackInput = document.getElementById('feedbackInput');

    // 初始化评分状态
    if (currentRating > 0) {
        highlightStars(currentRating, 'active');
        showRatingText(currentRating);
    }

    stars.forEach(star => {
        star.addEventListener('mouseenter', () => {
            const rating = parseInt(star.dataset.rating);
            highlightStars(rating, 'hover');
        });

        star.addEventListener('mouseleave', () => {
            highlightStars(currentRating, 'active');
        });

        star.addEventListener('click', () => {
            currentRating = parseInt(star.dataset.rating);
            highlightStars(currentRating, 'active');
            animateStars(currentRating);
            showRatingText(currentRating);
            // 保存评分状态到本地存储
            localStorage.setItem(RATING_KEY, currentRating);
            
            // 长辈模式下语音播报评分
            if (isSeniorMode) {
                speakText(`您选择了${currentRating}星评分`);
            }
        });
    });

    submitBtn.addEventListener('click', submitFeedback);

    feedbackInput.addEventListener('keypress', (e) => {
        if (e.key === 'Enter' && !e.shiftKey) {
            e.preventDefault();
            submitFeedback();
        }
    });
}

function highlightStars(rating, className) {
    const stars = document.querySelectorAll('.star');
    stars.forEach((star, index) => {
        star.classList.remove('active', 'hover');
        if (index < rating) {
            star.classList.add(className);
        }
    });
}

function animateStars(rating) {
    const stars = document.querySelectorAll('.star');
    stars.forEach((star, index) => {
        if (index < rating) {
            setTimeout(() => {
                star.classList.add('animate');
                setTimeout(() => {
                    star.classList.remove('animate');
                }, 400);
            }, index * 80);
        }
    });
}

function showRatingText(rating) {
    const ratingText = document.getElementById('ratingText');
    if (rating > 0) {
        ratingText.textContent = ratingTexts[rating];
        ratingText.classList.remove('hidden');
        ratingText.style.animation = 'none';
        void ratingText.offsetWidth;
        ratingText.style.animation = 'fadeIn 0.3s ease';
    } else {
        ratingText.classList.add('hidden');
    }
}

function submitFeedback() {
    const feedbackInput = document.getElementById('feedbackInput');
    const submitBtn = document.getElementById('submitFeedback');
    const content = feedbackInput.value.trim();

    if (currentRating === 0) {
        showToast('请先点亮星星评分～', 'warning');
        return;
    }

    if (!content) {
        showToast('请填写反馈内容～', 'warning');
        feedbackInput.focus();
        return;
    }

    const newFeedback = {
        id: Date.now(),
        rating: currentRating,
        content: content,
        timestamp: new Date().toLocaleDateString('zh-CN', { 
            year: 'numeric', 
            month: 'short', 
            day: 'numeric',
            hour: '2-digit',
            minute: '2-digit'
        })
    };

    feedbacks.unshift(newFeedback);
    saveFeedbacks();
    renderFeedbacksList(true);

    // 发放贝壳奖励
    const shellReward = 10;
    checkinData.shells += shellReward;
    saveCheckinData();
    updateShellBalance();
    
    // 记录贝壳奖励到明细
    const rewardRecord = {
        type: 'feedback',
        description: '反馈奖励',
        reward: shellReward,
        date: new Date().toISOString()
    };
    checkinData.rewards.push(rewardRecord);
    saveCheckinData();

    // 显示贝壳飞入动画
    const shellBadge = document.getElementById('shellBadge');
    if (shellBadge) {
        shellBadge.classList.add('shell-reward-animation');
        setTimeout(() => {
            shellBadge.classList.remove('shell-reward-animation');
        }, 1000);
    }

    feedbackInput.value = '';
    currentRating = 0;
    highlightStars(0, 'active');
    document.getElementById('ratingText').classList.add('hidden');
    // 清除本地存储的评分状态
    localStorage.removeItem(RATING_KEY);

    submitBtn.classList.add('success', 'submit-success');
    setTimeout(() => {
        submitBtn.classList.remove('success', 'submit-success');
    }, 1500);

    showFeedbackSuccessModal();
    showPrivateToast();
    // 显示贝壳奖励提示
    showToast(`感谢你的宝贵反馈！已为你发放${shellReward}个旅行贝壳`, 'success');
}

// 显示私密提示
function showPrivateToast() {
    const toast = document.getElementById('toast');
    const toastText = document.getElementById('toastText');
    
    const messages = [
        '✅ 反馈已私密保存，仅你可见！',
        '🔒 已收到你的反馈，仅本地存储～',
        '💾 反馈已保存，只有你能看到！',
        '🌟 感谢反馈，已私密记录！'
    ];
    const randomMessage = messages[Math.floor(Math.random() * messages.length)];
    
    toastText.textContent = randomMessage;
    toast.classList.remove('hidden', 'hide');
    toast.classList.add('show');
    
    setTimeout(() => {
        toast.classList.remove('show');
        toast.classList.add('hide');
        setTimeout(() => {
            toast.classList.add('hidden');
        }, 300);
    }, 3000);
}

function renderFeedbacksList(isNew = false, newId = null) {
    const feedbackList = document.getElementById('feedbackList');

    if (feedbacks.length === 0) {
        feedbackList.innerHTML = `
            <div class="text-center text-gray-400 py-8">
                <p class="text-5xl mb-3">💌</p>
                <p class="text-lg">还没有反馈呢</p>
                <p class="text-sm mt-1">期待你的使用感受～</p>
            </div>
        `;
        return;
    }

    feedbackList.innerHTML = '';

    feedbacks.forEach((fb, index) => {
        const div = document.createElement('div');
        div.className = 'feedback-card';

        if (isNew && fb.id === newId) {
            div.style.animationDelay = '0s';
        } else {
            div.style.animationDelay = `${Math.min(index * 0.05, 0.3)}s`;
        }

        let starsHtml = '';
        for (let i = 0; i < 5; i++) {
            starsHtml += `<span>${i < fb.rating ? '⭐' : '☆'}</span>`;
        }

        div.innerHTML = `
            <div class="feedback-header">
                <div class="feedback-rating">${starsHtml}</div>
                <span class="feedback-time">${fb.timestamp}</span>
            </div>
            <p class="feedback-content">${escapeHtml(fb.content)}</p>
            <div class="mt-2 text-xs text-green-600 flex items-center gap-1">
                <span>🔒</span>
                <span>仅你可见</span>
            </div>
        `;

        feedbackList.appendChild(div);
    });
}

function escapeHtml(text) {
    const div = document.createElement('div');
    div.textContent = text;
    return div.innerHTML;
}

