// 隐藏/折叠攻略
// 隐藏/折叠攻略
function toggleDayPlan(btn) {
    // 按钮动画反馈
    btn.style.transform = 'scale(0.9)';
    setTimeout(() => {
        btn.style.transform = '';
    }, 150);
    
    const card = btn.closest('.day-plan-card');
    const activities = card.querySelector('.day-activities');
    const icon = btn.querySelector('.toggle-icon');
    
    if (activities.classList.contains('collapsed')) {
        // 展开
        activities.classList.remove('collapsed');
        activities.style.maxHeight = activities.scrollHeight + 'px';
        activities.style.opacity = '1';
        icon.textContent = '🔽';
    } else {
        // 折叠
        activities.classList.add('collapsed');
        activities.style.maxHeight = '0';
        activities.style.opacity = '0';
        icon.textContent = '🔼';
    }
}

// 隐藏/折叠攻略
let guideExpanded = true;
function toggleGuide() {
    const toggleBtn = document.getElementById('toggleGuideBtn');
    const toggleIcon = document.getElementById('toggleIcon');
    const guideSections = document.querySelectorAll('#guideSection > div:not(:first-child)');
    
    if (!toggleBtn) return;
    
    // 按钮动画反馈
    toggleBtn.style.transform = 'scale(0.95)';
    setTimeout(() => {
        toggleBtn.style.transform = '';
    }, 150);

    guideExpanded = !guideExpanded;
    
    const btnSpan = toggleBtn.querySelector('span:last-child');
    
    if (guideExpanded) {
        // 展开攻略
        guideSections.forEach((section, index) => {
            setTimeout(() => {
                section.style.display = '';
                section.style.animation = 'fadeIn 0.5s ease-out';
            }, index * 50);
        });
        if (toggleIcon) toggleIcon.textContent = '🔽';
        if (btnSpan) btnSpan.textContent = '收起';
        showToast('攻略已展开', 'info');
    } else {
        // 折叠攻略
        guideSections.forEach((section, index) => {
            setTimeout(() => {
                section.style.animation = 'fadeOut 0.3s ease-in';
                setTimeout(() => {
                    section.style.display = 'none';
                }, 300);
            }, index * 30);
        });
        if (toggleIcon) toggleIcon.textContent = '🔼';
        if (btnSpan) btnSpan.textContent = '展开';
        showToast('攻略已收起', 'info');
    }
}

// 清空攻略
function clearGuide() {
    const clearBtn = document.getElementById('clearGuideBtn');
    
    // 按钮动画反馈
    if (clearBtn) {
        clearBtn.style.transform = 'scale(0.95)';
        setTimeout(() => {
            clearBtn.style.transform = '';
        }, 150);
    }

    // 清空攻略内容
    if (guideSection) guideSection.classList.add('hidden');
    document.querySelectorAll('section').forEach(s => s.classList.remove('hidden'));
    document.querySelectorAll('.max-w-4xl, .max-w-5xl').forEach(el => {
        if (!el.closest('#guideSection')) {
            el.classList.remove('hidden');
        }
    });

    // 重置状态
    selectedDestination = null;
    currentPlanTab = 'compact';
    currentRating = 0;
    
    // 清空输入框
    const recommendCity = document.getElementById('recommendCity');
    const recommendReason = document.getElementById('recommendReason');
    const feedbackInput = document.getElementById('feedbackInput');
    if (recommendCity) recommendCity.value = '';
    if (recommendReason) recommendReason.value = '';
    if (feedbackInput) feedbackInput.value = '';
    
    // 重置星级评分
    document.querySelectorAll('.star').forEach(star => {
        star.classList.remove('active');
    });
    document.getElementById('ratingText').classList.add('hidden');

    // 滚动到顶部
    window.scrollTo({ 
        top: 0, 
        behavior: 'smooth' 
    });

    showToast('攻略已清空', 'success');
}

// ==================== 旅行备忘录功能 ====================
const MEMO_KEY = 'travelPlannerMemo';
let memoSaveTimeout = null;

function loadMemo() {
    const savedMemo = localStorage.getItem(MEMO_KEY);
    if (savedMemo) {
        const memoData = JSON.parse(savedMemo);
        document.getElementById('memoLuggage').value = memoData.luggage || '';
        document.getElementById('memoReminders').value = memoData.reminders || '';
        document.getElementById('memoNotes').value = memoData.notes || '';
    }
}

function saveMemo() {
    const memoData = {
        luggage: document.getElementById('memoLuggage').value,
        reminders: document.getElementById('memoReminders').value,
        notes: document.getElementById('memoNotes').value
    };
    localStorage.setItem(MEMO_KEY, JSON.stringify(memoData));
    
    const saveStatus = document.getElementById('memoSaveStatus');
    saveStatus.classList.remove('opacity-0');
    saveStatus.classList.add('opacity-100');
    
    clearTimeout(memoSaveTimeout);
    memoSaveTimeout = setTimeout(() => {
        saveStatus.classList.remove('opacity-100');
        saveStatus.classList.add('opacity-0');
    }, 2000);
}

function setupMemoListeners() {
    const luggageInput = document.getElementById('memoLuggage');
    const remindersInput = document.getElementById('memoReminders');
    const notesInput = document.getElementById('memoNotes');
    
    if (luggageInput) luggageInput.addEventListener('input', saveMemo);
    if (remindersInput) remindersInput.addEventListener('input', saveMemo);
    if (notesInput) notesInput.addEventListener('input', saveMemo);
    
    loadMemo();
}

