// ==================== 收藏功能 ====================
const FAVORITES_KEY = 'travelPlannerFavorites';
let favorites = JSON.parse(localStorage.getItem(FAVORITES_KEY)) || [];

function loadFavorites() {
    renderFavoritesList();
}

function saveFavorites() {
    localStorage.setItem(FAVORITES_KEY, JSON.stringify(favorites));
}

function isCurrentGuideFavorited() {
    if (!selectedDestination) return false;
    return favorites.some(f => f.id === selectedDestination.id && 
        f.days === selectedOptions.days && 
        f.crowd === selectedOptions.crowd &&
        f.budget === selectedOptions.budget);
}

function toggleFavorite() {
    if (!selectedDestination) {
        showToast('请先生成攻略～', 'warning');
        return;
    }

    const favoriteBtn = document.getElementById('favoriteBtn');
    const favoriteIcon = document.getElementById('favoriteIcon');
    
    const guideData = {
        id: selectedDestination.id,
        title: guideTitle.textContent,
        subtitle: guideSubtitle.textContent,
        emoji: selectedDestination.emoji,
        name: selectedDestination.name,
        days: selectedOptions.days,
        crowd: selectedOptions.crowd,
        budget: selectedOptions.budget,
        timestamp: Date.now()
    };

    const existingIndex = favorites.findIndex(f => 
        f.id === guideData.id && 
        f.days === guideData.days && 
        f.crowd === guideData.crowd &&
        f.budget === guideData.budget
    );

    if (existingIndex > -1) {
        favorites.splice(existingIndex, 1);
        favoriteIcon.textContent = '🤍';
        favoriteBtn.classList.remove('favorited');
        showToast('已取消收藏', 'info');
    } else {
        favorites.unshift(guideData);
        favoriteIcon.textContent = '❤️';
        favoriteBtn.classList.add('favorited');
        showFavEasterEgg();
        const travelThemes = [
            '🌟 攻略已收藏，准备好出发了吗？',
            '✈️ 收藏成功！期待你的精彩旅程～',
            '🏖️ 攻略已保存，向着美好出发！',
            '🌍 收藏完成，旅行计划Get！',
            '🎒 攻略已加入收藏夹，准备开启冒险！'
        ];
        const randomTheme = travelThemes[Math.floor(Math.random() * travelThemes.length)];
        showToast(randomTheme, 'success');
    }

    saveFavorites();
    renderFavoritesList();
}

// ==================== 收藏成功动画 ====================
function showFavEasterEgg() {
    const easterEgg = document.createElement('div');
    easterEgg.className = 'fav-easter-egg fixed top-1/2 left-1/2 transform -translate-x-1/2 -translate-y-1/2 z-50 flex flex-col items-center';
    
    easterEgg.innerHTML = `
        <div class="easter-egg-emoji text-6xl animate-bounce">🧳</div>
        <div class="easter-egg-text mt-4 bg-white/90 backdrop-blur-sm rounded-full px-6 py-2 shadow-lg text-gray-800 font-semibold">
            已收藏，旅途必备✨
        </div>
    `;
    
    easterEgg.style.animation = 'slideInOut 2s ease-in-out forwards';
    
    document.body.appendChild(easterEgg);
    
    setTimeout(() => {
        if (easterEgg.parentNode) easterEgg.parentNode.removeChild(easterEgg);
    }, 2000);
}

function updateFavoriteButton() {
    const favoriteBtn = document.getElementById('favoriteBtn');
    const favoriteIcon = document.getElementById('favoriteIcon');
    
    if (isCurrentGuideFavorited()) {
        favoriteIcon.textContent = '❤️';
        favoriteBtn.classList.add('favorited');
    } else {
        favoriteIcon.textContent = '🤍';
        favoriteBtn.classList.remove('favorited');
    }
}

function renderFavoritesList() {
    const favoritesSection = document.getElementById('favoritesSection');
    const favoritesList = document.getElementById('favoritesList');
    const noFavorites = document.getElementById('noFavorites');

    if (favorites.length === 0) {
        favoritesSection.classList.add('hidden');
        return;
    }

    favoritesSection.classList.remove('hidden');
    favoritesList.innerHTML = '';

    const crowdNames = { solo: '独自旅行', couple: '情侣', family: '亲子', friends: '闺蜜', team: '团建' };
    const budgetNames = { budget: '穷游', normal: '平价', luxury: '轻奢' };

    favorites.forEach((fav, index) => {
        const div = document.createElement('div');
        div.className = 'favorite-card fade-in';
        div.style.animationDelay = `${index * 0.05}s`;
        
        div.innerHTML = `
            <div class="card-content" onclick="loadFavorite('${fav.id}', ${fav.days}, '${fav.crowd}', '${fav.budget}')">
                <span class="card-emoji">${fav.emoji}</span>
                <div class="card-info">
                    <h4>${fav.name} · ${fav.days}天${fav.days - 1}晚</h4>
                    <p>${crowdNames[fav.crowd]} · ${budgetNames[fav.budget]}</p>
                </div>
            </div>
            <div class="card-actions">
                <button class="action-icon view" onclick="loadFavorite('${fav.id}', ${fav.days}, '${fav.crowd}', '${fav.budget}')" title="查看">👁️</button>
                <button class="action-icon delete" onclick="deleteFavorite(${index})" title="删除">🗑️</button>
            </div>
        `;
        
        favoritesList.appendChild(div);
    });

    noFavorites.classList.add('hidden');
}

function loadFavorite(destId, days, crowd, budget) {
    const dest = destinations.find(d => d.id === destId);
    if (!dest) return;

    selectedOptions.days = days;
    selectedOptions.crowd = crowd;
    selectedOptions.budget = budget;

    const destBtn = document.querySelector(`.destination-btn[data-id="${destId}"]`);
    if (destBtn) {
        selectDestination(dest, destBtn);
    }

    setTimeout(() => {
        generateGuide();
        showToast('已加载收藏的攻略～', 'success');
        document.getElementById('guideSection').scrollIntoView({ behavior: 'smooth' });
    }, 100);
}

function deleteFavorite(index) {
    favorites.splice(index, 1);
    saveFavorites();
    renderFavoritesList();
    showToast('已删除收藏', 'info');
    
    if (isCurrentGuideFavorited()) {
        updateFavoriteButton();
    }
}

// ==================== 复制攻略功能 ====================
function copyGuideToClipboard() {
    if (!selectedDestination) {
        showToast('请先生成攻略～', 'warning');
        return;
    }

    const text = generateGuideText();
    
    navigator.clipboard.writeText(text).then(() => {
        showToast('攻略已复制到剪贴板！', 'success');
    }).catch(() => {
        fallbackCopyText(text);
    });
}

function generateGuideText() {
    const dest = selectedDestination;
    const days = parseInt(selectedOptions.days);
    const crowdNames = { solo: '独自旅行', couple: '甜蜜情侣', family: '亲子家庭', friends: '闺蜜好友', team: '团队出行' };
    const budgetNames = { budget: '穷游版', normal: '平价版', luxury: '轻奢版' };

    let text = `${'='.repeat(40)}\n`;
    text += `🌟 ${dest.name}旅行攻略 🌟\n`;
    text += `${'='.repeat(40)}\n`;
    text += `${days}天${days - 1}晚 · ${crowdNames[selectedOptions.crowd]} · ${budgetNames[selectedOptions.budget]}\n\n`;

    text += `📍 推荐目的地\n`;
    text += `${dest.cities.map((c, i) => `${i + 1}. ${c.name} ${c.emoji}`).join('\n')}\n\n`;

    text += `${'─'.repeat(40)}\n`;
    text += `📅 ${currentPlanTab === 'compact' ? '方案A：紧凑高效版' : '方案B：佛系懒人版'}\n`;
    text += `${'─'.repeat(40)}\n`;
    
    const planContent = currentPlanTab === 'compact' 
        ? document.getElementById('planAContent') 
        : document.getElementById('planBContent');
    
    const dayCards = planContent.querySelectorAll('.day-plan-card');
    dayCards.forEach(card => {
        const dayHeader = card.querySelector('.day-header');
        const dayNumber = dayHeader.querySelector('.day-number').textContent;
        const dayTheme = dayHeader.querySelector('.day-theme').textContent;
        text += `\n${dayNumber} ${dayTheme}\n`;
        
        const activities = card.querySelectorAll('.activity-item');
        activities.forEach(act => {
            const time = act.querySelector('.activity-time').textContent;
            const content = act.querySelector('.activity-content').textContent;
            text += `  ${time} ${content}\n`;
        });
    });

    text += `\n${'─'.repeat(40)}\n`;
    text += `🚗 交通建议\n`;
    text += `${'─'.repeat(40)}\n`;
    const transports = document.querySelectorAll('#transportContent .transport-card');
    transports.forEach(t => {
        const icon = t.querySelector('.text-2xl').textContent;
        const name = t.querySelector('h4').textContent;
        const desc = t.querySelector('.text-sm.text-gray-600').textContent;
        text += `${icon} ${name}: ${desc}\n`;
    });

    text += `\n${'─'.repeat(40)}\n`;
    text += `🍜 必吃美食\n`;
    text += `${'─'.repeat(40)}\n`;
    const foods = document.querySelectorAll('#foodContent .food-card');
    foods.forEach(f => {
        const emoji = f.querySelector('.text-3xl').textContent;
        const name = f.querySelector('h4').textContent;
        const desc = f.querySelector('.text-sm.text-gray-600').textContent;
        text += `${emoji} ${name}: ${desc}\n`;
    });

    text += `\n${'─'.repeat(40)}\n`;
    text += `🏨 住宿推荐\n`;
    text += `${'─'.repeat(40)}\n`;
    const hotels = document.querySelectorAll('#hotelContent .hotel-card');
    hotels.forEach(h => {
        const emoji = h.querySelector('.text-3xl').textContent;
        const name = h.querySelector('h4').textContent;
        const tags = h.querySelectorAll('.hotel-tag');
        const tagsText = Array.from(tags).map(t => t.textContent).join(' ');
        text += `${emoji} ${name} ${tagsText}\n`;
    });

    text += `\n${'─'.repeat(40)}\n`;
    text += `⚠️ 避坑提醒\n`;
    text += `${'─'.repeat(40)}\n`;
    const avoids = document.querySelectorAll('#avoidContent .avoid-card');
    avoids.forEach(a => {
        const icon = a.querySelector('.text-2xl').textContent;
        const title = a.querySelector('h4').textContent;
        const desc = a.querySelector('.text-sm').textContent;
        text += `${icon} ${title}: ${desc}\n`;
    });

    text += `\n${'─'.repeat(40)}\n`;
    text += `💰 预算估算\n`;
    text += `${'─'.repeat(40)}\n`;
    const budgets = document.querySelectorAll('#budgetContent .budget-item');
    budgets.forEach(b => {
        const name = b.querySelector('.budget-name').textContent;
        const value = b.querySelector('.budget-value').textContent;
        text += `${name}: ${value}\n`;
    });

    text += `\n${'='.repeat(40)}\n`;
    text += `✨ 祝你旅途愉快 ✨\n`;

    return text;
}

function fallbackCopyText(text) {
    const textarea = document.createElement('textarea');
    textarea.value = text;
    textarea.style.position = 'fixed';
    textarea.style.opacity = '0';
    document.body.appendChild(textarea);
    textarea.select();
    try {
        document.execCommand('copy');
        showToast('攻略已复制到剪贴板！', 'success');
    } catch (err) {
        showToast('复制失败，请手动选择文本复制', 'error');
    }
    document.body.removeChild(textarea);
}

// ==================== 分享功能 ====================
function shareGuide() {
    if (!selectedDestination) {
        showToast('请先生成攻略～', 'warning');
        return;
    }

    showShareMenu();
}

// ==================== Toast提示 ====================
function showToast(message, type = 'info') {
    const toast = document.getElementById('toast');
    const toastText = document.getElementById('toastText');

    toast.classList.remove('hidden', 'show', 'hide');
    toastText.textContent = message;

    const icons = {
        success: '✅',
        error: '❌',
        warning: '⚠️',
        info: '💡'
    };
    toastText.textContent = `${icons[type] || '💡'} ${message}`;

    void toast.offsetWidth;
    toast.classList.add('show');

    setTimeout(() => {
        toast.classList.remove('show');
        toast.classList.add('hide');
        setTimeout(() => {
            toast.classList.add('hidden');
        }, 300);
    }, 2000);
}

